import { sql } from 'drizzle-orm'
import { sqliteTable, text, integer, unique, index, check } from 'drizzle-orm/sqlite-core'

// ============================================================================
// COMPOSABLE COLUMN PRIMITIVES
// Change pricing logic = one edit. All line-item tables spread these.
// ============================================================================

/** Shared pricing contract for every line item in the system */
export const lineItemColumns = {
  lineType: text('line_type', { enum: ['part', 'labor', 'bicycle'] }).notNull(),
  partId: text('part_id').references(() => parts.id),
  laborServiceId: text('labor_service_id').references(() => laborServices.id),
  description: text('description').notNull(),
  quantity: integer('quantity', { mode: 'number' }).notNull().default(1),
  unitPriceNet: integer('unit_price_net', { mode: 'number' }).notNull(), // ex-tax cents per unit
  vatRateId: text('vat_rate_id').references(() => vatRates.id).notNull(), // FK to vatRates lookup
  discountPercent: integer('discount_percent'), // basis points, nullable = no discount
  lineTotalNet: integer('line_total_net', { mode: 'number' }).notNull(), // discounted net total
  lineTotalVat: integer('line_total_vat', { mode: 'number' }).notNull(), // VAT amount
  lineTotalGross: integer('line_total_gross', { mode: 'number' }).notNull(), // incl-tax total
}

/** Bicycle-specific details for bicycle line items */
export const bicycleLineColumns = {
  bicycleId: text('bicycle_id').references(() => bicycles.id), // link to physical instance
  bicycleBrand: text('bicycle_brand'),
  bicycleModel: text('bicycle_model'),
  bicycleYear: integer('bicycle_year', { mode: 'number' }),
  bicycleColor: text('bicycle_color'),
  bicycleFrameSize: text('bicycle_frame_size'),
}

/** CHECK constraints for line item tables — applied per-table via extras callback */
export const lineItemChecks = () => ({
  totalsNonNegative: check(
    'line_totals_non_negative',
    sql`${sql.identifier('line_total_net')} >= 0 AND ${sql.identifier('line_total_vat')} >= 0 AND ${sql.identifier('line_total_gross')} >= 0`
  ),
})

// ============================================================================
// CORE ENTITIES — Customers, Staff, Tax
// ============================================================================

/** Who we serve — private individuals or companies. Anonymous walk-ins have no row. */
export const customers = sqliteTable('customers', {
  id: text('id').primaryKey(),
  type: text('type', { enum: ['private', 'company'] }).notNull().default('private'),
  firstName: text('first_name'), // required for private
  lastName: text('last_name'), // required for private
  companyName: text('company_name'), // required for company
  vatId: text('vat_id'), // for companies
  phone: text('phone'),
  email: text('email'),
  street: text('street'),
  number: text('number'),
  bus: text('bus'),
  postalCode: text('postal_code'),
  city: text('city'),
  country: text('country').notNull().default('BE'), // Belgium default
  notificationPreference: text('notification_preference', { enum: ['sms', 'email'] }),
})

export type Customer = typeof customers.$inferSelect
export type NewCustomer = typeof customers.$inferInsert

/** Shop staff — mechanics and managers with hourly rates */
export const users = sqliteTable('users', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  role: text('role', { enum: ['mechanic', 'manager'] }).notNull().default('mechanic'),
  hourlyRate: integer('hourly_rate', { mode: 'number' }).notNull(),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
})

export type User = typeof users.$inferSelect
export type NewUser = typeof users.$inferInsert

/** VAT rate lookup — e.g. standard 21%, reduced 6% */
export const vatRates = sqliteTable('vat_rates', {
  id: text('id').primaryKey(),
  rate: integer('rate').notNull().unique(), // basis points: 2100 = 21%, 600 = 6%
  description: text('description').notNull(),
})

export type VatRate = typeof vatRates.$inferSelect
export type NewVatRate = typeof vatRates.$inferInsert

// ============================================================================
// CATALOG — Parts, Labor Services, Bicycle Templates
// ============================================================================

/** Physical products with stock tracking */
export const parts = sqliteTable('parts', {
  id: text('id').primaryKey(),
  barcode: text('barcode').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
  priceNet: integer('price_net', { mode: 'number' }).notNull(), // ex-tax cents
  costPrice: integer('cost_price', { mode: 'number' }), // in cents
  quantityOnHand: integer('quantity_on_hand', { mode: 'number' }).notNull().default(0),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
}, (table) => ({
  activeIdx: index('parts_active_idx').on(table.isActive),
}))

export type Part = typeof parts.$inferSelect
export type NewPart = typeof parts.$inferInsert

/** Labor services — hourly or fixed-rate work types */
export const laborServices = sqliteTable('labor_services', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  description: text('description'),
  billingType: text('billing_type', { enum: ['hourly', 'fixed'] }).notNull(),
  defaultRate: integer('default_rate', { mode: 'number' }).notNull(), // cents/hour or fixed amount
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
})

export type LaborService = typeof laborServices.$inferSelect
export type NewLaborService = typeof laborServices.$inferInsert

/** Bicycle catalog templates — become real bicycles when sold or taken in */
export const bicycleTemplates = sqliteTable('bicycle_templates', {
  id: text('id').primaryKey(),
  brand: text('brand').notNull(),
  model: text('model').notNull(),
  description: text('description'),
  basePriceNet: integer('base_price_net', { mode: 'number' }), // optional catalog price in cents
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
})

export type BicycleTemplate = typeof bicycleTemplates.$inferSelect
export type NewBicycleTemplate = typeof bicycleTemplates.$inferInsert

// ============================================================================
// BICYCLES — Physical Instances
// ============================================================================

/** Real bicycles — customer-owned or shop inventory */
export const bicycles = sqliteTable('bicycles', {
  id: text('id').primaryKey(),
  source: text('source', { enum: ['inventory', 'customer_owned'] }).notNull().default('customer_owned'),
  templateId: text('template_id').references(() => bicycleTemplates.id), // nullable for customer-owned
  customerId: text('customer_id').references(() => customers.id), // required when source = 'customer_owned'
  brand: text('brand').notNull(), // snapshotted from template or entered manually
  model: text('model').notNull(),
  year: integer('year', { mode: 'number' }),
  color: text('color'),
  frameSize: text('frame_size'),
  isLease: integer('is_lease', { mode: 'boolean' }).notNull().default(false), // true when bicycle is sold under lease
  status: text('status', { enum: ['inventory', 'in_shop', 'ready_for_pickup', 'returned', 'sold'] })
    .notNull().default('inventory'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('bicycles_customer_id_idx').on(table.customerId),
  sourceCustomerCheck: check(
    'bicycles_source_customer_check',
    sql`(${sql.identifier('source')} = 'customer_owned' AND ${sql.identifier('customer_id')} IS NOT NULL) OR (${sql.identifier('source')} = 'inventory' AND ${sql.identifier('customer_id')} IS NULL)`
  ),
}))

export type Bicycle = typeof bicycles.$inferSelect
export type NewBicycle = typeof bicycles.$inferInsert

// ============================================================================
// WORKING DOCUMENTS — Quotes, Repairs, Customer Orders, Backorders
// ============================================================================

/** Estimates/proposals — immutable once sent. Copied to Order or Repair on approval. */
export const quotes = sqliteTable('quotes', {
  id: text('id').primaryKey(),
  quoteNumber: text('quote_number').notNull().unique(), // QT-0001
  customerId: text('customer_id').references(() => customers.id), // nullable during draft
  status: text('status', { enum: ['draft', 'sent', 'converted', 'rejected'] })
    .notNull().default('draft'),
  notes: text('notes'),
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
  updatedAt: integer('updated_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  statusIdx: index('quotes_status_idx').on(table.status),
  customerRequiredCheck: check(
    'quotes_customer_required_check',
    sql`${sql.identifier('status')} = 'draft' OR ${sql.identifier('customer_id')} IS NOT NULL`
  ),
}))

export type Quote = typeof quotes.$inferSelect
export type NewQuote = typeof quotes.$inferInsert

/** Quote line items — snapshotted pricing per line */
export const quoteLineItems = sqliteTable('quote_line_items', {
  id: text('id').primaryKey(),
  quoteId: text('quote_id').notNull().references(() => quotes.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  quoteIdIdx: index('quote_line_items_quote_id_idx').on(table.quoteId),
  ...lineItemChecks(),
}))

export type QuoteLineItem = typeof quoteLineItems.$inferSelect
export type NewQuoteLineItem = typeof quoteLineItems.$inferInsert

// ---------------------------------------------------------------------------
/** Repair work tracking — links bicycle, worker, and line items */
export const repairs = sqliteTable('repairs', {
  id: text('id').primaryKey(),
  bicycleId: text('bicycle_id').notNull().references(() => bicycles.id),
  assignedTo: text('assigned_to').references(() => users.id),
  status: text('status', { enum: ['intake', 'in_progress', 'on_hold', 'ready', 'completed', 'cancelled'] })
    .notNull().default('intake'),
  customerNotes: text('customer_notes'),
  internalNotes: text('internal_notes'), // technician observations during work
  holdReason: text('hold_reason', { enum: ['waiting_parts', 'awaiting_customer_approval', 'other'] }),
  holdReasonNote: text('hold_reason_note'),
  plannedDate: integer('planned_date', { mode: 'number' }), // scheduled start/completion date
  pickupDate: integer('pickup_date', { mode: 'number' }), // customer collection date
  completedAt: integer('completed_at', { mode: 'number' }),
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  statusIdx: index('repairs_status_idx').on(table.status),
  holdReasonNoteCheck: check(
    'repairs_hold_reason_note_check',
    sql`${sql.identifier('hold_reason')} IS NULL OR ${sql.identifier('hold_reason_note')} IS NOT NULL`
  ),
}))

export type Repair = typeof repairs.$inferSelect
export type NewRepair = typeof repairs.$inferInsert

/** Repair line items — parts used and labor logged. minutesWorked is billing-specific; workLogs is the source of truth for actual time worked (payroll). */
export const repairLineItems = sqliteTable('repair_line_items', {
  id: text('id').primaryKey(),
  repairId: text('repair_id').notNull().references(() => repairs.id),
  ...lineItemColumns,
  minutesWorked: integer('minutes_worked', { mode: 'number' }), // billing minutes; may differ from workLogs (payroll)
  hourlyRateSnapshot: integer('hourly_rate_snapshot', { mode: 'number' }), // worker's rate at time of logging
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  repairIdIdx: index('repair_line_items_repair_id_idx').on(table.repairId),
  ...lineItemChecks(),
}))

export type RepairLineItem = typeof repairLineItems.$inferSelect
export type NewRepairLineItem = typeof repairLineItems.$inferInsert

/** Timer sessions per repair — source of truth for actual time worked (payroll). Billing minutes are in repairLineItems. */
export const workLogs = sqliteTable('work_logs', {
  id: text('id').primaryKey(),
  repairId: text('repair_id').notNull().references(() => repairs.id),
  userId: text('user_id').notNull().references(() => users.id),
  startedAt: integer('started_at', { mode: 'number' }).notNull(),
  endedAt: integer('ended_at', { mode: 'number' }), // null if timer still running
}, (table) => ({
  repairIdIdx: index('work_logs_repair_id_idx').on(table.repairId),
}))

export type WorkLog = typeof workLogs.$inferSelect
export type NewWorkLog = typeof workLogs.$inferInsert

/** Repair status audit trail — every transition recorded */
export const repairStatusHistory = sqliteTable('repair_status_history', {
  id: text('id').primaryKey(),
  repairId: text('repair_id').notNull().references(() => repairs.id),
  status: text('status', { enum: ['intake', 'in_progress', 'on_hold', 'ready', 'completed', 'cancelled'] }).notNull(),
  transitionedAt: integer('transitioned_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  repairIdTransitionedIdx: index('repair_status_history_repair_trans_idx').on(table.repairId, table.transitionedAt),
}))

export type RepairStatusHistory = typeof repairStatusHistory.$inferSelect
export type NewRepairStatusHistory = typeof repairStatusHistory.$inferInsert

// ---------------------------------------------------------------------------
/** Customer orders — non-instant fulfillment requests (parts or bicycles) */
export const customerOrders = sqliteTable('customer_orders', {
  id: text('id').primaryKey(),
  orderNumber: text('order_number').notNull().unique(), // CO-0001
  customerId: text('customer_id').notNull().references(() => customers.id),
  status: text('status', { enum: ['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'] })
    .notNull().default('pending'),
  totalPriceNet: integer('total_price_net', { mode: 'number' }).notNull(), // locked at creation, cents
  expectedDeliveryDate: integer('expected_delivery_date', { mode: 'timestamp' }),
  internalNotes: text('internal_notes'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('customer_orders_customer_id_idx').on(table.customerId),
  statusIdx: index('customer_orders_status_idx').on(table.status),
}))

export type CustomerOrder = typeof customerOrders.$inferSelect
export type NewCustomerOrder = typeof customerOrders.$inferInsert

/** Line items for customer orders */
export const customerOrderLineItems = sqliteTable('customer_order_line_items', {
  id: text('id').primaryKey(),
  orderId: text('customer_order_id').notNull().references(() => customerOrders.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  orderIdIdx: index('customer_order_line_items_order_id_idx').on(table.orderId),
  ...lineItemChecks(),
}))

export type CustomerOrderLineItem = typeof customerOrderLineItems.$inferSelect
export type NewCustomerOrderLineItem = typeof customerOrderLineItems.$inferInsert

// ---------------------------------------------------------------------------
/** Backorders — parts not in stock, with deposit tracking via payment allocations */
export const backorders = sqliteTable('backorders', {
  id: text('id').primaryKey(),
  customerId: text('customer_id').notNull().references(() => customers.id),
  totalPriceNet: integer('total_price_net', { mode: 'number' }).notNull(), // locked at creation, cents
  status: text('status', { enum: ['requested', 'ordered', 'arrived', 'completed', 'cancelled'] })
    .notNull().default('requested'),
  expectedDeliveryDate: integer('expected_delivery_date', { mode: 'timestamp' }),
  internalNotes: text('internal_notes'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('backorders_customer_id_idx').on(table.customerId),
  statusIdx: index('backorders_status_idx').on(table.status),
}))

// NOTE: depositPaid is DERIVED from payment_allocations WHERE targetType='backorder' AND targetId=X
// Do NOT store it as a column — query the allocations.

export type Backorder = typeof backorders.$inferSelect
export type NewBackorder = typeof backorders.$inferInsert

/** Line items for backorders */
export const backorderLineItems = sqliteTable('backorder_line_items', {
  id: text('id').primaryKey(),
  backorderId: text('backorder_id').notNull().references(() => backorders.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  backorderIdIdx: index('backorder_line_items_backorder_id_idx').on(table.backorderId),
  ...lineItemChecks(),
}))

export type BackorderLineItem = typeof backorderLineItems.$inferSelect
export type NewBackorderLineItem = typeof backorderLineItems.$inferInsert

/** Backorder status audit trail */
export const backorderStatusHistory = sqliteTable('backorder_status_history', {
  id: text('id').primaryKey(),
  backorderId: text('backorder_id').notNull().references(() => backorders.id),
  status: text('status', { enum: ['requested', 'ordered', 'arrived', 'completed', 'cancelled'] }).notNull(),
  transitionedAt: integer('transitioned_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  backorderIdTransitionedIdx: index('backorder_status_history_backorder_trans_idx').on(table.backorderId, table.transitionedAt),
}))

export type BackorderStatusHistory = typeof backorderStatusHistory.$inferSelect
export type NewBackorderStatusHistory = typeof backorderStatusHistory.$inferInsert

// ============================================================================
// FINAL DOCUMENTS — Sales (Receipts) and Invoices
// ============================================================================

/** Paid transactions / receipts — immutable once created. Source of truth for completed commerce. */
export const sales = sqliteTable('sales', {
  id: text('id').primaryKey(),
  saleNumber: text('sale_number').notNull().unique(), // SA-0001
  customerId: text('customer_id').references(() => customers.id), // nullable for anonymous/walk-in
  sourceType: text('source_type', { enum: ['direct_sale', 'repair', 'customer_order', 'backorder'] }).notNull(),
  sourceId: text('source_id'), // ID of source document (nullable for direct_sale)
  status: text('status', { enum: ['completed', 'voided'] }).notNull().default('completed'),
  subtotalNet: integer('subtotal_net', { mode: 'number' }).notNull(), // ex-tax cents
  vatTotal: integer('vat_total', { mode: 'number' }).notNull(), // VAT in cents
  totalGross: integer('total_gross', { mode: 'number' }).notNull(), // incl-tax cents
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  sourceIdx: index('sales_source_idx').on(table.sourceType, table.sourceId),
}))

export type Sale = typeof sales.$inferSelect
export type NewSale = typeof sales.$inferInsert

/** Line items for sales — immutable snapshot at time of payment */
export const saleLineItems = sqliteTable('sale_line_items', {
  id: text('id').primaryKey(),
  saleId: text('sale_id').notNull().references(() => sales.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  saleIdIdx: index('sale_line_items_sale_id_idx').on(table.saleId),
  ...lineItemChecks(),
}))

export type SaleLineItem = typeof saleLineItems.$inferSelect
export type NewSaleLineItem = typeof saleLineItems.$inferInsert

/** Optional legal/financial snapshot from a Sale — immutable copy of line items */
export const invoices = sqliteTable('invoices', {
  id: text('id').primaryKey(),
  invoiceNumber: text('invoice_number').notNull().unique(), // INV-0001
  saleId: text('sale_id').notNull().unique().references(() => sales.id),
  customerId: text('customer_id').references(() => customers.id), // denormalized from sale for lookup
  status: text('status', { enum: ['issued', 'sent'] }).notNull().default('issued'),
  subtotalNet: integer('subtotal_net', { mode: 'number' }).notNull(),
  vatTotal: integer('vat_total', { mode: 'number' }).notNull(),
  totalGross: integer('total_gross', { mode: 'number' }).notNull(),
  issuedAt: integer('issued_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('invoices_customer_id_idx').on(table.customerId),
}))

export type Invoice = typeof invoices.$inferSelect
export type NewInvoice = typeof invoices.$inferInsert

/** Line items for invoices — immutable snapshot copied from Sale */
export const invoiceLineItems = sqliteTable('invoice_line_items', {
  id: text('id').primaryKey(),
  invoiceId: text('invoice_id').notNull().references(() => invoices.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  invoiceIdIdx: index('invoice_line_items_invoice_id_idx').on(table.invoiceId),
  ...lineItemChecks(),
}))

export type InvoiceLineItem = typeof invoiceLineItems.$inferSelect
export type NewInvoiceLineItem = typeof invoiceLineItems.$inferInsert

// ============================================================================
// PAYMENTS — Polymorphic Allocation to Any Document Type
// ============================================================================

/** Payment records — one payment can settle multiple documents */
export const payments = sqliteTable('payments', {
  id: text('id').primaryKey(),
  method: text('method', { enum: ['cash', 'card', 'bank_transfer'] }).notNull(),
  amount: integer('amount', { mode: 'number' }).notNull(), // in cents, total payment amount
  referenceNumber: text('reference_number'), // e.g. POS receipt number
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  createdAtIdx: index('payments_created_at_idx').on(table.createdAt),
}))

export type Payment = typeof payments.$inferSelect
export type NewPayment = typeof payments.$inferInsert

/** Junction table — one payment → many document targets */
export const paymentAllocations = sqliteTable('payment_allocations', {
  id: text('id').primaryKey(),
  paymentId: text('payment_id').notNull().references(() => payments.id),
  targetType: text('target_type', { enum: ['sale', 'customer_order', 'backorder', 'repair', 'invoice'] }).notNull(),
  targetId: text('target_id').notNull(), // ID of the target document
  allocatedAmount: integer('allocated_amount', { mode: 'number' }).notNull(), // in cents
}, (table) => ({
  paymentIdIdx: index('payment_allocations_payment_id_idx').on(table.paymentId),
  targetIdx: index('payment_allocations_target_idx').on(table.targetType, table.targetId),
}))

// NOTE: depositPaid on backorders = SUM(allocatedAmount) WHERE targetType='backorder' AND targetId=X

export type PaymentAllocation = typeof paymentAllocations.$inferSelect
export type NewPaymentAllocation = typeof paymentAllocations.$inferInsert

// ============================================================================
// SUPPLIER & INVENTORY — Internal Procurement and Stock Audit
// ============================================================================

/** Supplier product cache from external APIs — NOT the source of truth for inventory.
 * Extracted fields (sellPrice, costPrice) are parsed from rawJson at read time via a typed parser module.
 * No denormalized columns — prevents drift between stored fields and source data. */
export const supplierProducts = sqliteTable('supplier_products', {
  id: text('id').primaryKey(),
  eanUpc: text('ean_upc').notNull(),
  rawJson: text('raw_json').notNull(), // full supplier product JSON blob — single source of truth
  supplierName: text('supplier_name').notNull(),
  searchedAt: integer('searched_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  // Composite unique constraint: same EAN can appear with different suppliers
  eanSupplierUnique: unique('supplier_products_ean_supplier_unique').on(table.eanUpc, table.supplierName),
}))

export type SupplierProduct = typeof supplierProducts.$inferSelect
export type NewSupplierProduct = typeof supplierProducts.$inferInsert

/** Internal supplier orders — shop procurement, not customer-facing */
export const supplierOrders = sqliteTable('supplier_orders', {
  id: text('id').primaryKey(),
  supplierName: text('supplier_name').notNull(),
  status: text('status', { enum: ['pending', 'ordered', 'received'] }).notNull().default('pending'),
  referenceNumber: text('reference_number'),
  orderedAt: integer('ordered_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  statusIdx: index('supplier_orders_status_idx').on(table.status),
}))

export type SupplierOrder = typeof supplierOrders.$inferSelect
export type NewSupplierOrder = typeof supplierOrders.$inferInsert

/** Line items for supplier orders */
export const supplierOrderLines = sqliteTable('supplier_order_lines', {
  id: text('id').primaryKey(),
  orderId: text('order_id').notNull().references(() => supplierOrders.id),
  eanUpc: text('ean_upc').notNull(),
  partId: text('part_id').references(() => parts.id), // nullable until imported into local catalog
  quantityOrdered: integer('quantity_ordered', { mode: 'number' }).notNull().default(1),
  quantityReceived: integer('quantity_received', { mode: 'number' }).notNull().default(0),
}, (table) => ({
  orderIdIdx: index('supplier_order_lines_order_id_idx').on(table.orderId),
}))

export type SupplierOrderLine = typeof supplierOrderLines.$inferSelect
export type NewSupplierOrderLine = typeof supplierOrderLines.$inferInsert

// ============================================================================
// SUPPLIER CATALOG — Gransier (extracted columns, not raw JSON)
// ============================================================================

/** Gransier product catalog — extracted from FTPS CSV download.
 * Unlike Kruitbosch (rawJson), Gransier data is stored with denormalized columns
 * because it's used directly in search and import workflows. */
export const gransierProducts = sqliteTable('gransier_products', {
  id: text('id').primaryKey(),
  eanUpc: text('ean_upc').notNull().unique(),
  itemNumber: text('item_number'),
  brand: text('brand'),
  name: text('name').notNull(),
  description: text('description'),
  costPriceNet: integer('cost_price_net', { mode: 'number' }), // ex-tax cents
  sellPriceNet: integer('sell_price_net', { mode: 'number' }).notNull(), // ex-tax cents
  vatRateBasisPoints: integer('vat_rate_basis_points').notNull().default(2100), // e.g. 2100 = 21%
  imageUrl: text('image_url'),
  category: text('category'),
  color: text('color'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
}, (table) => ({
  eanIdx: index('gransier_products_ean_idx').on(table.eanUpc),
  nameBrandIdx: index('gransier_products_name_brand_idx').on(table.name, table.brand),
}))

