import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import toast from 'react-hot-toast'
import { ArrowLeft, Package, Wrench, Bike } from 'lucide-react'
import type { CustomerOrderStatus } from '../types.js'
import { ORDER_STATUS_LABELS, ORDER_STATUS_COLORS, LINE_TYPE_LABELS } from '../types.js'
import { getOrder, updateOrderStatus, type OrderDetailApiResponse } from '../api.js'
import { formatCentsToEuro } from '@/shared/lib/utils'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface OrderDetailPanelProps {
  orderId: string
}

/** Status transitions allowed from each state */
const STATUS_TRANSITIONS: Record<CustomerOrderStatus, Array<{ to: CustomerOrderStatus; label: string }>> = {
  pending: [
    { to: 'ordered', label: 'Mark Ordered' },
    { to: 'cancelled', label: 'Cancel Order' },
  ],
  ordered: [
    { to: 'ready', label: 'Mark Ready for Pickup' },
    { to: 'cancelled', label: 'Cancel Order' },
  ],
  ready: [
    { to: 'fulfilled', label: 'Mark Fulfilled' },
    { to: 'cancelled', label: 'Cancel Order' },
  ],
  fulfilled: [], // terminal state
  cancelled: [], // terminal state
}

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: CustomerOrderStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[status]}`}>
      {ORDER_STATUS_LABELS[status]}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Line Type Icon
// ---------------------------------------------------------------------------

function LineTypeIcon({ lineType }: { lineType: string }) {
  switch (lineType) {
    case 'part': return <Package className="h-4 w-4 text-muted-foreground" />
    case 'labor': return <Wrench className="h-4 w-4 text-muted-foreground" />
    case 'bicycle': return <Bike className="h-4 w-4 text-muted-foreground" />
    default: return null
  }
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

// ---------------------------------------------------------------------------
// Component — Order Detail Panel
// ---------------------------------------------------------------------------

export function OrderDetailPanel({ orderId }: OrderDetailPanelProps) {
  const navigate = useNavigate()
  const [detail, setDetail] = useState<OrderDetailApiResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [transitioning, setTransitioning] = useState(false)

  // Fetch order detail
  const fetchOrder = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const data = await getOrder(orderId)
      setDetail(data)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load order')
    } finally {
      setLoading(false)
    }
  }, [orderId])

  useEffect(() => {
    fetchOrder()
  }, [fetchOrder])

  // Handle status transition
  const handleTransition = async (newStatus: CustomerOrderStatus) => {
    setTransitioning(true)
    try {
      await updateOrderStatus(orderId, newStatus)
      toast.success(`Order marked as ${ORDER_STATUS_LABELS[newStatus].toLowerCase()}`)
      await fetchOrder()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update status')
    } finally {
      setTransitioning(false)
    }
  }

  // Back to list
  const handleBack = () => navigate('/orders')

  if (loading) {
    return (
      <div className="flex flex-col h-full">
        <CardHeader className="pb-2 px-6 pt-4">
          <CardTitle className="text-xl">Loading order…</CardTitle>
        </CardHeader>
      </div>
    )
  }

  if (error || !detail) {
    return (
      <div className="flex flex-col h-full">
        <CardHeader className="pb-2 px-6 pt-4">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="sm" onClick={handleBack}>
              <ArrowLeft className="h-4 w-4 mr-1" /> Back
            </Button>
          </div>
        </CardHeader>
        <CardContent className="px-6 pb-6">
          <div className="p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error || 'Order not found'}
          </div>
        </CardContent>
      </div>
    )
  }

  const { order, lineItems, depositPaid } = detail
  const availableTransitions = STATUS_TRANSITIONS[order.status] ?? []

  // Compute totals from line items
  const totalNet = lineItems.reduce((sum, item) => sum + item.lineTotalNet, 0)
  const totalVat = lineItems.reduce((sum, item) => sum + item.lineTotalVat, 0)
  const totalGross = lineItems.reduce((sum, item) => sum + item.lineTotalGross, 0)

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="sm" onClick={handleBack}>
              <ArrowLeft className="h-4 w-4 mr-1" /> Back
            </Button>
            <CardTitle className="text-xl">{order.orderNumber}</CardTitle>
            <StatusBadge status={order.status} />
          </div>

          {/* Status transition buttons */}
          {availableTransitions.length > 0 && (
            <div className="flex gap-2">
              {availableTransitions.map((transition) => (
                <Button
                  key={transition.to}
                  variant={transition.to === 'cancelled' ? 'outline' : 'default'}
                  size="sm"
                  onClick={() => handleTransition(transition.to)}
                  disabled={transitioning}
                  className={transition.to === 'cancelled' ? 'text-red-600 hover:text-red-700 border-red-200' : ''}
                >
                  {transition.label}
                </Button>
              ))}
            </div>
          )}
        </div>
      </CardHeader>

      {/* Content */}
      <CardContent className="px-6 pb-6 flex-1 overflow-auto space-y-6">
        {/* Order Info Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
          <div>
            <span className="text-muted-foreground block text-xs">Customer</span>
            <span className="font-medium">{order.customerId ? `ID: ${order.customerId.slice(0, 8)}…` : 'Unknown'}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Created</span>
            <span>{formatDate(order.createdAt)}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Expected Delivery</span>
            <span>{formatDate(order.expectedDeliveryDate)}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Deposit Paid</span>
            <span className="font-mono">{formatCentsToEuro(depositPaid)}</span>
          </div>
        </div>

        {/* Internal Notes */}
        {order.internalNotes && (
          <div className="p-3 bg-muted/50 rounded-md text-sm">
            <span className="text-muted-foreground block text-xs mb-1">Internal Notes</span>
            <span>{order.internalNotes}</span>
          </div>
        )}

        {/* Line Items Table */}
        <div>
          <h3 className="text-sm font-medium text-muted-foreground mb-2">Line Items ({lineItems.length})</h3>
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50 border-b">
                  <th className="text-left px-4 py-2 font-medium text-muted-foreground w-16">Type</th>
                  <th className="text-left px-4 py-2 font-medium text-muted-foreground">Description</th>
                  <th className="text-center px-4 py-2 font-medium text-muted-foreground w-16">Qty</th>
                  <th className="text-right px-4 py-2 font-medium text-muted-foreground w-28">Unit Price</th>
                  <th className="text-right px-4 py-2 font-medium text-muted-foreground w-28">Total (net)</th>
                </tr>
              </thead>
              <tbody>
                {lineItems.map((item) => (
                  <tr key={item.id} className="border-b last:border-b-0 hover:bg-muted/30 transition-colors">
                    <td className="px-4 py-2">
                      <div className="flex items-center gap-1.5">
                        <LineTypeIcon lineType={item.lineType} />
                        <span className="text-xs text-muted-foreground">{LINE_TYPE_LABELS[item.lineType as keyof typeof LINE_TYPE_LABELS] ?? item.lineType}</span>
                      </div>
                    </td>
                    <td className="px-4 py-2">{item.description}</td>
                    <td className="px-4 py-2 text-center tabular-nums">{item.quantity}</td>
                    <td className="px-4 py-2 text-right font-mono tabular-nums">{formatCentsToEuro(item.unitPriceNet)}</td>
                    <td className="px-4 py-2 text-right font-mono tabular-nums">{formatCentsToEuro(item.lineTotalNet)}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="bg-muted/30">
                  <td colSpan={4} className="px-4 py-2 text-right font-medium">Totals:</td>
                  <td className="px-4 py-2 text-right font-mono tabular-nums">
                    <div className="text-xs space-y-0.5">
                      <div className="flex justify-between gap-8">
                        <span className="text-muted-foreground">Net:</span>
                        <span>{formatCentsToEuro(totalNet)}</span>
                      </div>
                      <div className="flex justify-between gap-8 text-xs text-muted-foreground">
                        <span>VAT:</span>
                        <span>{formatCentsToEuro(totalVat)}</span>
                      </div>
                      <div className="flex justify-between gap-8 font-medium border-t pt-1 mt-1">
                        <span>Gross:</span>
                        <span>{formatCentsToEuro(totalGross)}</span>
                      </div>
                    </div>
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        {/* Deposit Summary */}
        {depositPaid > 0 && (
          <div className="p-4 bg-accent rounded-md text-sm">
            <h3 className="font-medium mb-2">Deposit Summary</h3>
            <div className="grid grid-cols-3 gap-4">
              <div>
                <span className="text-muted-foreground block text-xs">Total (net)</span>
                <span className="font-mono">{formatCentsToEuro(totalNet)}</span>
              </div>
              <div>
                <span className="text-muted-foreground block text-xs">Deposit Paid</span>
                <span className="font-mono text-green-600 dark:text-green-400">{formatCentsToEuro(depositPaid)}</span>
              </div>
              <div>
                <span className="text-muted-foreground block text-xs">Balance Due</span>
                <span className="font-mono">{formatCentsToEuro(Math.max(0, totalNet - depositPaid))}</span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </div>
  )
}

import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { customerOrders, customerOrderLineItems, payments, paymentAllocations, sequences, vatRates, bicycles } from '@/db/schema.js'
import { eq } from 'drizzle-orm'

describe('Customer Orders Routes — Integration Tests', () => {
  async function resetTables() {
    await db.delete(paymentAllocations)
    await db.delete(payments)
    await db.delete(customerOrderLineItems)
    await db.delete(customerOrders)
    await db.delete(vatRates)
    try { await db.delete(bicycles) } catch {}
    try { await db.delete(sequences).where(eq(sequences.name, 'customer_order')) } catch {}
  }

  beforeEach(async () => {
    await resetTables()
  })

  // ---------------------------------------------------------------------------
  // POST /api/orders — Create a customer order
  // ---------------------------------------------------------------------------
  describe('POST /api/orders', () => {
    it('should create a customer order without deposit (tracer bullet)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part',
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 2,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)

      const json = await res.json() as Record<string, unknown>
      expect(json.order).toBeDefined()
      expect((json.order as Record<string, unknown>).customerId).toBe('cust-abc-123')
      expect((json.order as Record<string, unknown>).status).toBe('pending')
      expect((json.order as Record<string, unknown>).orderNumber).toMatch(/^CO-\d{4}$/)
      expect((json.order as Record<string, unknown>).totalPriceNet).toBe(2000)

      // No payment when no deposit
      expect(json.payment).toBeUndefined()
      expect(json.allocation).toBeUndefined()

      // Line items created
      const lineItems = json.lineItems as Record<string, unknown>[]
      expect(lineItems).toHaveLength(1)
      expect(lineItems[0].lineType).toBe('part')
    })

    it('should create a customer order with deposit payment', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part',
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 1,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
        depositAmount: 500,
        paymentMethod: 'card',
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)

      const json = await res.json() as Record<string, unknown>
      // Payment record created
      expect(json.payment).toBeDefined()
      expect((json.payment as Record<string, unknown>).amount).toBe(500)
      expect((json.payment as Record<string, unknown>).method).toBe('card')

      // Allocation links payment to order
      expect(json.allocation).toBeDefined()
      const allocation = json.allocation as Record<string, unknown>
      expect(allocation.targetType).toBe('customer_order')
      expect(allocation.allocatedAmount).toBe(500)
    })

    it('should reject deposit when leased bicycle present (409)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(bicycles).values({
        id: 'bike-lease-1',
        source: 'inventory' as const,
        brand: 'Trek',
        model: 'Domane',
        isLease: true,
        status: 'inventory' as const,
      })

      const body = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'bicycle',
            bicycleId: 'bike-lease-1',
            description: 'Trek Domane (leased)',
            quantity: 1,
            unitPriceNet: 50000,
            vatRateId: 'vat-standard',
          },
        ],
        depositAmount: 2500,
        paymentMethod: 'cash',
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(409)
      const json = await res.json() as Record<string, unknown>
      expect(json.code).toBe('LEASED_BICYCLE_DEPOSIT')
    })

    it('should reject missing customerId (400)', async () => {
      const body = {
        customerId: '',
        lineItems: [
          { lineType: 'part', partId: 'p1', description: 'Test', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-std' },
        ],
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })

    it('should reject empty line items (400)', async () => {
      const body = { customerId: 'cust-abc', lineItems: [] }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })

    it('should reject deposit without paymentMethod (400)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Test', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
        depositAmount: 500,
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })
  })

  // ---------------------------------------------------------------------------
  // GET /api/orders — List customer orders
  // ---------------------------------------------------------------------------
  describe('GET /api/orders', () => {
    it('should return empty list when no orders exist', async () => {
      const res = await app.request('/api/orders')

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.orders).toEqual([])
      expect(json.total).toBe(0)
    })

    it('should filter by status', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      // Create two orders via direct DB insert (simpler for this test)
      const orderId1 = crypto.randomUUID()
      const orderId2 = crypto.randomUUID()
      await db.insert(customerOrders).values([
        { id: orderId1, orderNumber: 'CO-0001', customerId: 'cust-a', status: 'pending', totalPriceNet: 1000, createdAt: new Date() },
        { id: orderId2, orderNumber: 'CO-0002', customerId: 'cust-b', status: 'ordered', totalPriceNet: 2000, createdAt: new Date() },
      ])

      const res = await app.request('/api/orders?status=pending')

      expect(res.status).toBe(200)
      const json = await res.json() as { orders: Array<Record<string, unknown>>; total: number }
      expect(json.orders).toHaveLength(1)
      expect((json.orders[0] as Record<string, unknown>).id).toBe(orderId1)
    })
  })

  // ---------------------------------------------------------------------------
  // GET /api/orders/:id — Get order detail
  // ---------------------------------------------------------------------------
  describe('GET /api/orders/:id', () => {
    it('should return 404 for non-existent order', async () => {
      const res = await app.request('/api/orders/nonexistent-id')

      expect(res.status).toBe(404)
    })

    it('should return order detail with depositPaid derived from allocations', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      // Create order via API (with deposit)
      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
        depositAmount: 500,
        paymentMethod: 'cash',
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Fetch detail
      const res = await app.request(`/api/orders/${orderId}`)

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.depositPaid).toBe(500)
      expect((json.order as Record<string, unknown>).id).toBe(orderId)
    })
  })

  // ---------------------------------------------------------------------------
  // PATCH /api/orders/:id/status — Transition status
  // ---------------------------------------------------------------------------
  describe('PATCH /api/orders/:id/status', () => {
    it('should transition order from pending to ordered', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Transition to ordered
      const res = await app.request(`/api/orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect((json.order as Record<string, unknown>).status).toBe('ordered')
    })

    it('should return 404 for non-existent order', async () => {
      const res = await app.request('/api/orders/nonexistent-id/status', {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(404)
    })

    it('should reject invalid status (400)', async () => {
      const res = await app.request('/api/orders/some-id/status', {
        method: 'PATCH',
        body: JSON.stringify({ status: 'invalid_status' }),
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(400)
    })
  })
})

/**
 * Pure functions for line item price calculations.
 *
 * All amounts in cents (integer). Discount and VAT rates are in basis points
 * (100 = 1%, 2100 = 21%). No framework dependencies — importable from both
 * client and server.
 *
 * This is the single source of truth for line math, replacing duplicated
 * implementations in client store and server service.
 */

// ============================================================================
// Line Item Math
// ============================================================================

/**
 * Compute line item totals from quantity, unit price, discount, and VAT rate.
 *
 * Formula: discountedNetPerUnit = unitPriceNet × (1 - discountBps / 10000)
 *          lineNetTotal = discountedNetPerUnit × quantity
 *          lineVatTotal = round(lineNetTotal × vatRateBps / 10000)
 *          lineGrossTotal = lineNetTotal + lineVatTotal
 *
 * @param unitPriceNet — Ex-tax price per unit in cents (integer)
 * @param quantity — Number of units (integer, >= 1)
 * @param discountPercentBps — Discount in basis points (null or 0 = no discount). e.g. 1000 = 10%
 * @param vatRateBps — VAT rate in basis points. e.g. 2100 = 21%, 600 = 6%
 * @returns Object with net, vat, and gross totals in cents (integer)
 */
export function computeLineTotals(
  unitPriceNet: number,
  quantity: number,
  discountPercentBps: number | null | undefined,
  vatRateBps: number
): { net: number; vat: number; gross: number } {
  // Apply discount (basis points → fraction)
  const discountFactor = discountPercentBps ? 1 - discountPercentBps / 10000 : 1
  const discountedNetPerUnit = Math.round(unitPriceNet * discountFactor)
  const lineNetTotal = discountedNetPerUnit * quantity

  // Compute VAT (round to nearest cent)
  const lineVatTotal = Math.round(lineNetTotal * vatRateBps / 10000)

  return {
    net: lineNetTotal,
    vat: lineVatTotal,
    gross: lineNetTotal + lineVatTotal
  }
}

