import { describe, it, expect, beforeEach } from 'vitest'
import { db } from '@/db/index.js'
import {
  customerOrders,
  customerOrderLineItems,
  customerOrderStatusHistory,
  payments,
  paymentAllocations,
  sales,
  saleLineItems,
  sequences,
  vatRates,
  bicycles,
  notifications,
} from '@/db/schema.js'
import { eq } from 'drizzle-orm'

describe('Customer Order Lifecycle — Integration Tests', () => {
  async function resetTables() {
    await db.delete(notifications)
    await db.delete(paymentAllocations)
    await db.delete(payments)
    await db.delete(saleLineItems)
    await db.delete(sales)
    await db.delete(customerOrderStatusHistory)
    await db.delete(customerOrderLineItems)
    await db.delete(customerOrders)
    await db.delete(vatRates)
    try { await db.delete(bicycles) } catch {}
    try { await db.delete(sequences).where(eq(sequences.name, 'customer_order')) } catch {}
    try { await db.delete(sequences).where(eq(sequences.name, 'sale')) } catch {}
  }

  beforeEach(async () => {
    await resetTables()
    // Seed VAT rate used by all tests
    await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
  })

  // Helper: create an order via the service (reuse existing createCustomerOrder)
  async function createTestOrder(depositAmount = 0) {
    const { createCustomerOrder } = await import('../customer-order.service.js')
    return createCustomerOrder({
      customerId: 'cust-abc',
      lineItems: [
        { lineType: 'part' as const, partId: 'p1', description: 'Part A', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard' },
      ],
      ...(depositAmount > 0 ? { depositAmount, paymentMethod: 'cash' as const } : {}),
    })
  }

  // ============================================================================
  // transitionCustomerOrder — Status transitions with validation + history
  // ============================================================================

  describe('transitionCustomerOrder', () => {
    it('(tracer) should transition pending → ordered and record history', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const result = await transitionCustomerOrder(order.order.id, 'ordered')

      expect(result.status).toBe('ordered')
      // History entry created
      const history = await db.select().from(customerOrderStatusHistory).where(eq(customerOrderStatusHistory.orderId, order.order.id))
      expect(history).toHaveLength(1)
      expect(history[0].status).toBe('ordered')
    })

    it('should transition ordered → ready', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')

      const result = await transitionCustomerOrder(order.order.id, 'ready')
      expect(result.status).toBe('ready')
    })

    it('should transition ready → fulfilled', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      const result = await transitionCustomerOrder(order.order.id, 'fulfilled')
      expect(result.status).toBe('fulfilled')
    })

    it('should allow cancel from any non-terminal status', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // Cancel from pending
      let result = await transitionCustomerOrder(order.order.id, 'cancelled')
      expect(result.status).toBe('cancelled')
    })

    it('should reject invalid transitions', async () => {
      const { transitionCustomerOrder, InvalidTransitionError } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // pending → fulfilled (skips ordered + ready) should fail
      await expect(transitionCustomerOrder(order.order.id, 'fulfilled')).rejects.toThrow(InvalidTransitionError)
    })

    it('should reject transition from terminal state', async () => {
      const { transitionCustomerOrder, InvalidTransitionError } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')
      await transitionCustomerOrder(order.order.id, 'fulfilled')

      // fulfilled → anything should fail
      await expect(transitionCustomerOrder(order.order.id, 'ordered')).rejects.toThrow(InvalidTransitionError)
    })

    it('should reject duplicate status transition', async () => {
      const { transitionCustomerOrder, InvalidTransitionError } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // pending → pending (no change) should fail
      await expect(transitionCustomerOrder(order.order.id, 'pending')).rejects.toThrow(InvalidTransitionError)
    })

    it('should set expectedDeliveryDate when provided during transition', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      const deliveryDate = new Date('2026-07-15').toISOString()

      const result = await transitionCustomerOrder(order.order.id, 'ordered', { expectedDeliveryDate: deliveryDate })
      expect(result.expectedDeliveryDate).toBeInstanceOf(Date)
    })

    it('should set internalNotes when provided during transition', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const result = await transitionCustomerOrder(order.order.id, 'ordered', { internalNotes: 'Rush order' })
      expect(result.internalNotes).toBe('Rush order')
    })

    it('should throw for non-existent order', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      await expect(transitionCustomerOrder('nonexistent-id', 'ordered')).rejects.toThrow(/not found/i)
    })

    it('should create notification when transitioning to ready', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      // Insert a customer with SMS preference
      await db.insert(customerOrders).values({
        id: 'order-with-customer',
        orderNumber: 'CO-TEST1',
        customerId: 'cust-sms',
        status: 'ordered',
        totalPriceNet: 2000,
        createdAt: new Date(),
      })

      await transitionCustomerOrder('order-with-customer', 'ready')

      const notifications = await db.select().from(notifications)
      expect(notifications.length).toBeGreaterThan(0)
    })
  })

  // ============================================================================
  // updateCustomerOrderFields — Editable fields with guards
  // ============================================================================

  describe('updateCustomerOrderFields', () => {
    it('(tracer) should update internalNotes on pending order', async () => {
      const { updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const result = await updateCustomerOrderFields(order.order.id, { internalNotes: 'Updated notes' })
      expect(result.internalNotes).toBe('Updated notes')
    })

    it('should update expectedDeliveryDate on ordered order', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')

      const deliveryDate = new Date('2026-08-01').toISOString()
      const result = await updateCustomerOrderFields(order.order.id, { expectedDeliveryDate: deliveryDate })
      expect(result.expectedDeliveryDate).toBeInstanceOf(Date)
    })

    it('should allow updates through ready status', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      // Should still be editable at ready status
      const result = await updateCustomerOrderFields(order.order.id, { internalNotes: 'Final notes' })
      expect(result.internalNotes).toBe('Final notes')
    })

    it('should reject updates on fulfilled order (403)', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields, EditabilityError } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      // Complete the order (fulfilled) — use direct DB update for this test since completeOrder is tested separately
      await db.update(customerOrders).set({ status: 'fulfilled' }).where(eq(customerOrders.id, order.order.id))

      await expect(updateCustomerOrderFields(order.order.id, { internalNotes: 'Should fail' })).rejects.toThrow(EditabilityError)
    })

    it('should reject updates on cancelled order (403)', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields, EditabilityError } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'cancelled')

      await expect(updateCustomerOrderFields(order.order.id, { internalNotes: 'Should fail' })).rejects.toThrow(EditabilityError)
    })

    it('should throw for non-existent order', async () => {
      const { updateCustomerOrderFields } = await import('../customer-order.service.js')
      await expect(updateCustomerOrderFields('nonexistent-id', { internalNotes: 'test' })).rejects.toThrow(/not found/i)
    })

    it('should reject empty update payload', async () => {
      const { updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // @ts-expect-error — testing runtime validation
      await expect(updateCustomerOrderFields(order.order.id, {})).rejects.toThrow(/nothing to update/i)
    })
  })

  // ============================================================================
  // completeCustomerOrder — Balance collection → sale record → fulfilled
  // ============================================================================

  describe('completeCustomerOrder', () => {
    it('(tracer) should collect balance and create sale for order with deposit', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 1500 },
      ])

      // Order is fulfilled
      expect(result.order.status).toBe('fulfilled')

      // Sale created with correct sourceType
      expect(result.sale.sourceType).toBe('customer_order')
      expect(result.sale.sourceId).toBe(order.order.id)

      // Payment record created for balance
      expect(result.payment.amount).toBe(1500)
    })

    it('should collect balance with multiple payment methods', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 800 },
        { method: 'card', amount: 700 },
      ])

      expect(result.order.status).toBe('fulfilled')
      // Two payments created
      expect(result.payments).toHaveLength(2)
    })

    it('should create sale with line items copied from order', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500)

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 1500 },
      ])

      expect(result.saleLineItems).toHaveLength(1)
      expect(result.saleLineItems[0].description).toBe('Part A')
    })

    it('should reject when payment lines do not cover balance due', async () => {
      const { completeCustomerOrder, InsufficientPaymentError } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      await expect(completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 1000 }, // only 1000 of 1500 needed
      ])).rejects.toThrow(InsufficientPaymentError)
    })

    it('should reject when payment lines exceed balance due', async () => {
      const { completeCustomerOrder, InsufficientPaymentError } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      await expect(completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 2000 }, // exceeds 1500 needed
      ])).rejects.toThrow(InsufficientPaymentError)
    })

    it('should complete order with no deposit (full balance = totalPriceNet)', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder() // 2000 total, 0 deposit → 2000 balance

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'card', amount: 2000 },
      ])

      expect(result.order.status).toBe('fulfilled')
      expect(result.payment.amount).toBe(2000)
    })

    it('should reject completing already fulfilled order', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await completeCustomerOrder(order.order.id, [{ method: 'cash', amount: 2000 }])

      // Try to complete again
      await expect(completeCustomerOrder(order.order.id, [{ method: 'cash', amount: 2000 }])).rejects.toThrow(/already fulfilled/i)
    })

    it('should reject completing cancelled order', async () => {
      const { transitionCustomerOrder, completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'cancelled')

      await expect(completeCustomerOrder(order.order.id, [{ method: 'cash', amount: 2000 }])).rejects.toThrow(/cannot complete cancelled/i)
    })

    it('should throw for non-existent order', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      await expect(completeCustomerOrder('nonexistent-id', [{ method: 'cash', amount: 1000 }])).rejects.toThrow(/not found/i)
    })
  })

  // ============================================================================
  // cancelCustomerOrder — Cancel with refund rules
  // ============================================================================

  describe('cancelCustomerOrder', () => {
    it('(tracer) should cancel pending order and reverse deposit allocation', async () => {
      const { cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // with deposit

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      // Refund payment created
      expect(result.refundPayment).toBeDefined()
      expect(result.refundPayment!.amount).toBe(500)
    })

    it('should not create refund when cancelling pending order with no deposit', async () => {
      const { cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder() // no deposit

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      expect(result.refundPayment).toBeUndefined()
    })

    it('should NOT refund deposit when cancelling at ordered status', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // with deposit
      await transitionCustomerOrder(order.order.id, 'ordered')

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      // No refund at ordered status — deposit is non-refundable
      expect(result.refundPayment).toBeUndefined()
    })

    it('should NOT refund deposit when cancelling at ready status', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // with deposit
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      expect(result.refundPayment).toBeUndefined()
    })

    it('should reject cancelling already fulfilled order', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      // Manually set to fulfilled for this test (completeOrder tested separately)
      await db.update(customerOrders).set({ status: 'fulfilled' }).where(eq(customerOrders.id, order.order.id))

      await expect(cancelCustomerOrder(order.order.id)).rejects.toThrow(/cannot cancel fulfilled/i)
    })

    it('should reject cancelling already cancelled order', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'cancelled')

      await expect(cancelCustomerOrder(order.order.id)).rejects.toThrow(/already cancelled/i)
    })

    it('should throw for non-existent order', async () => {
      const { cancelCustomerOrder } = await import('../customer-order.service.js')
      await expect(cancelCustomerOrder('nonexistent-id')).rejects.toThrow(/not found/i)
    })
  })

  // ============================================================================
  // getCustomerOrderHistory — Status transition history
  // ============================================================================

  describe('getCustomerOrderHistory', () => {
    it('(tracer) should return empty array for order with no transitions', async () => {
      const { getCustomerOrderHistory } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const history = await getCustomerOrderHistory(order.order.id)
      expect(history).toEqual([])
    })

    it('should return transitions in chronological order (oldest first)', async () => {
      const { transitionCustomerOrder, getCustomerOrderHistory } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      await transitionCustomerOrder(order.order.id, 'ordered')
      // Small delay to ensure different timestamps
      await new Promise(r => setTimeout(r, 10))
      await transitionCustomerOrder(order.order.id, 'ready')

      const history = await getCustomerOrderHistory(order.order.id)

      expect(history).toHaveLength(2)
      expect(history[0].status).toBe('ordered')
      expect(history[1].status).toBe('ready')
    })

    it('should throw for non-existent order', async () => {
      const { getCustomerOrderHistory } = await import('../customer-order.service.js')
      await expect(getCustomerOrderHistory('nonexistent-id')).rejects.toThrow(/not found/i)
    })
  })
})

