/** Error thrown when deposit is attempted on an order containing leased bicycles */
export class LeasedBicycleDepositError extends Error {
  constructor() {
    super('Deposit collection not allowed for orders containing leased bicycles')
    this.name = 'LeasedBicycleDepositError'
  }
}

/** Error thrown when a status transition is invalid */
export class InvalidTransitionError extends Error {
  constructor(currentStatus: string, requestedStatus: string) {
    super(`Cannot transition from '${currentStatus}' to '${requestedStatus}'`)
    this.name = 'InvalidTransitionError'
  }
}

/** Error thrown when fields cannot be edited in current status */
export class EditabilityError extends Error {
  constructor(status: string) {
    super(`Fields are locked at '${status}' status. Only editable through 'ready'.`)
    this.name = 'EditabilityError'
  }
}

/** Error thrown when payment lines do not exactly cover balance due */
export class InsufficientPaymentError extends Error {
  constructor(public readonly expected: number, public readonly provided: number) {
    super(`Payment must exactly cover balance due. Expected ${expected}, got ${provided}`)
    this.name = 'InsufficientPaymentError'
  }
}

// ============================================================================
// Lifecycle Types
// ============================================================================

/** Optional fields that can be set during a status transition */
export interface TransitionOptions {
  expectedDeliveryDate?: string | null
  internalNotes?: string | null
}

/** A single payment line for balance collection */
export interface PaymentLine {
  method: 'cash' | 'card' | 'bank_transfer'
  amount: number // in cents
}

/** Result of completing a customer order with balance collection */
export interface CompleteOrderResult {
  /** Updated order (now fulfilled) */
  order: typeof customerOrders.$inferSelect
  /** Sale record created for the balance payment */
  sale: typeof sales.$inferSelect
  /** Payment records created (one per payment line) */
  payments: typeof payments.$inferSelect[]
  /** Line items copied to the sale */
  saleLineItems: typeof saleLineItems.$inferSelect[]
}

/** Result of cancelling a customer order */
export interface CancelOrderResult {
  /** Updated order (now cancelled) */
  status: CustomerOrderStatus
  /** Refund payment created (only when cancelled at 'pending' with deposit > 0) */
  refundPayment?: typeof payments.$inferSelect
}

// ============================================================================
// Allowed Status Transitions
// ============================================================================

/** Defines which transitions are allowed from each status */
const ALLOWED_TRANSITIONS: Record<CustomerOrderStatus, CustomerOrderStatus[]> = {
  pending: ['ordered', 'cancelled'],
  ordered: ['ready', 'cancelled'],
  ready: ['fulfilled', 'cancelled'],
  fulfilled: [], // terminal
  cancelled: [], // terminal
}

/** Statuses where fields are editable */
const EDITABLE_STATUSES: CustomerOrderStatus[] = ['pending', 'ordered', 'ready']

