/**
 * Transition a customer order to a new status with validation.
 *
 * Validates the transition is allowed, records history, and optionally sets
 * expectedDeliveryDate/internalNotes. Creates notification when transitioning to 'ready'.
 */
export async function transitionCustomerOrder(
  orderId: string,
  newStatus: CustomerOrderStatus,
  options?: TransitionOptions
): Promise<typeof customerOrders.$inferSelect> {
  // Fetch current order
  const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  if (!order) {
    throw new Error(`Customer order not found: ${orderId}`)
  }

  // Validate transition is allowed
  const allowed = ALLOWED_TRANSITIONS[order.status]
  if (!allowed.includes(newStatus)) {
    throw new InvalidTransitionError(order.status, newStatus)
  }

  // Build update payload
  const updates: Record<string, unknown> = { status: newStatus }
  if (options?.expectedDeliveryDate) {
    updates.expectedDeliveryDate = new Date(options.expectedDeliveryDate)
  }
  if (options?.internalNotes !== undefined && options.internalNotes !== null) {
    updates.internalNotes = options.internalNotes
  }

  // Execute transition in transaction
  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => client.prepare(sqlStr).run(...(params ?? []))

  try {
    run('BEGIN TRANSACTION')

    // Update order status (+ optional fields)
    const setClauses = Object.entries(updates).map(([key]) => `${key} = ?`)
    const values = Object.values(updates)
    run(
      `UPDATE customer_orders SET ${setClauses.join(', ')} WHERE id = ?`,
      [...values, orderId]
    )

    // Record history entry
    const historyId = crypto.randomUUID()
    run(
      'INSERT INTO customer_order_status_history (id, customer_order_id, status, transitioned_at) VALUES (?, ?, ?, ?)',
      [historyId, orderId, newStatus, Date.now()]
    )

    // Create notification when transitioning to 'ready'
    if (newStatus === 'ready') {
      const notificationId = crypto.randomUUID()
      run(
        `INSERT INTO notifications (id, customer_id, source_type, source_id, channel, message, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          notificationId,
          order.customerId,
          'customer_order',
          orderId,
          'sms', // default channel; could be made configurable
          `Your order ${order.orderNumber} is ready for pickup!`,
          'pending',
          Date.now(),
        ]
      )
    }

    run('COMMIT')
  } catch (err) {
    try { run('ROLLBACK') } catch {}
    throw err
  }

  // Fetch and return updated order
  const [updated] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  return updated!
}

/**
 * Update editable fields on a customer order.
 *
 * Fields (internalNotes, expectedDeliveryDate) are editable through 'ready' status.
 * Locked at 'fulfilled' and 'cancelled'.
 */
export async function updateCustomerOrderFields(
  orderId: string,
  updates: { internalNotes?: string | null; expectedDeliveryDate?: string | null }
): Promise<typeof customerOrders.$inferSelect> {
  // Validate there's something to update
  if (updates.internalNotes === undefined && updates.expectedDeliveryDate === undefined) {
    throw new Error('Nothing to update — provide internalNotes or expectedDeliveryDate')
  }

  // Fetch current order
  const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  if (!order) {
    throw new Error(`Customer order not found: ${orderId}`)
  }

  // Check editability guard
  if (!EDITABLE_STATUSES.includes(order.status)) {
    throw new EditabilityError(order.status)
  }

  // Build update payload
  const setClauses: string[] = []
  const values: unknown[] = []

  if (updates.internalNotes !== undefined) {
    setClauses.push('internal_notes = ?')
    values.push(updates.internalNotes)
  }
  if (updates.expectedDeliveryDate !== undefined) {
    setClauses.push('expected_delivery_date = ?')
    values.push(updates.expectedDeliveryDate ? new Date(updates.expectedDeliveryDate) : null)
  }

  values.push(orderId)

  await db.execute(
    `UPDATE customer_orders SET ${setClauses.join(', ')} WHERE id = ?`
  ).values(...values)

  // Fetch and return updated order
  const [updated] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  return updated!
}

/**
 * Complete a customer order by collecting balance payment.
 *
 * Creates a Sale record (sourceType='customer_order'), payment records,
 * and transitions the order to 'fulfilled'.
 */
export async function completeCustomerOrder(
  orderId: string,
  paymentLines: PaymentLine[]
): Promise<CompleteOrderResult> {
  // Fetch current order
  const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  if (!order) {
    throw new Error(`Customer order not found: ${orderId}`)
  }

  // Validate status — cannot complete cancelled or already fulfilled orders
  if (order.status === 'cancelled') {
    throw new Error('Cannot complete a cancelled order')
  }
  if (order.status === 'fulfilled') {
    throw new Error('Order is already fulfilled')
  }

  // Calculate balance due: totalPriceNet - depositPaid
  const [{ depositPaid }] = await db
    .select({ depositPaid: sql<number>`COALESCE(${sum(paymentAllocations.allocatedAmount)}, 0)` })
    .from(paymentAllocations)
    .where(
      and(
        eq(paymentAllocations.targetType, 'customer_order'),
        eq(paymentAllocations.targetId, orderId)
      )
    )

  const balanceDue = order.totalPriceNet - Number(depositPaid)
  const totalProvided = paymentLines.reduce((sum, line) => sum + line.amount, 0)

  // Payment must exactly cover balance due
  if (totalProvided !== balanceDue) {
    throw new InsufficientPaymentError(balanceDue, totalProvided)
  }

  // Fetch order line items to copy to sale
  const orderLineItems = await db.select()
    .from(customerOrderLineItems)
    .where(eq(customerOrderLineItems.orderId, orderId))
    .orderBy(asc(customerOrderLineItems.createdAt))

  // Fetch VAT rates for computing sale totals
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // Compute sale totals from order line items
  let subtotalNet = 0
  let vatTotal = 0
  for (const item of orderLineItems) {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(
      item.unitPriceNet,
      item.quantity,
      item.discountPercent ?? null,
      vatRateBps
    )
    subtotalNet += totals.net
    vatTotal += totals.vat
  }
  const totalGross = subtotalNet + vatTotal

  // Generate sale number
  const saleNumberSeq = await getNextSequenceValue('sale')
  const saleNumber = `SA-${String(saleNumberSeq).padStart(4, '0')}`

  // Execute in transaction
  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => client.prepare(sqlStr).run(...(params ?? []))

  const saleId = crypto.randomUUID()
  const paymentIds = paymentLines.map(() => crypto.randomUUID())
  const now = Date.now()

  try {
    run('BEGIN TRANSACTION')

    // Update order to fulfilled
    run(
      'UPDATE customer_orders SET status = ? WHERE id = ?',
      ['fulfilled', orderId]
    )

    // Record history entry for fulfilled transition
    const historyId = crypto.randomUUID()
    run(
      'INSERT INTO customer_order_status_history (id, customer_order_id, status, transitioned_at) VALUES (?, ?, ?, ?)',
      [historyId, orderId, 'fulfilled', now]
    )

    // Create sale record
    run(
      'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [saleId, saleNumber, order.customerId, 'customer_order', orderId, 'completed', subtotalNet, vatTotal, totalGross, now]
    )

    // Copy line items to sale
    for (const item of orderLineItems) {
      const lineItemId = crypto.randomUUID()
      run(
        'INSERT INTO sale_line_items (id, sale_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, bicycle_id, bicycle_brand, bicycle_model, bicycle_year, bicycle_color, bicycle_frame_size, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [
          lineItemId,
          saleId,
          item.lineType,
          item.partId,
          item.laborServiceId,
          item.description,
          item.quantity,
          item.unitPriceNet,
          item.vatRateId,
          item.discountPercent,
          item.lineTotalNet,
          item.lineTotalVat,
          item.lineTotalGross,
          item.bicycleId,
          item.bicycleBrand,
          item.bicycleModel,
          item.bicycleYear,
          item.bicycleColor,
          item.bicycleFrameSize,
          now,
        ]
      )
    }

    // Create payment records and allocations for each payment line
    for (let i = 0; i < paymentLines.length; i++) {
      const line = paymentLines[i]
      run(
        'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
        [paymentIds[i], line.method, line.amount, now]
      )

      // Allocate payment to the sale
      const allocationId = crypto.randomUUID()
      run(
        'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
        [allocationId, paymentIds[i], 'sale', saleId, line.amount]
      )
    }

    run('COMMIT')
  } catch (err) {
    try { run('ROLLBACK') } catch {}
    throw err
  }

  // Fetch and return results
  const [updatedOrder] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  const [createdSale] = await db.select().from(sales).where(eq(sales.id, saleId))
  const createdPayments = await db.select().from(payments).where(sql`${payments.id} IN (${sql.join(paymentIds)})`)
  const saleLineItemRows = await db.select().from(saleLineItems).where(eq(saleLineItems.saleId, saleId)).orderBy(asc(saleLineItems.createdAt))

  return {
    order: updatedOrder!,
    sale: createdSale!,
    payments: createdPayments,
    saleLineItems: saleLineItemRows,
  }
}

/**
 * Cancel a customer order with refund rules applied.
 *
 * - At 'pending': reverses deposit allocation + creates refund payment (if deposit exists)
 * - At 'ordered' or later: deposit is non-refundable, no automatic financial adjustment
 */
export async function cancelCustomerOrder(orderId: string): Promise<CancelOrderResult> {
  // Fetch current order
  const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  if (!order) {
    throw new Error(`Customer order not found: ${orderId}`)
  }

  // Validate — cannot cancel already fulfilled or cancelled orders
  if (order.status === 'fulfilled') {
    throw new Error('Cannot cancel a fulfilled order')
  }
  if (order.status === 'cancelled') {
    throw new Error('Order is already cancelled')
  }

  // Determine refund eligibility: only at 'pending' status with deposit > 0
  const [{ depositPaid }] = await db
    .select({ depositPaid: sql<number>`COALESCE(${sum(paymentAllocations.allocatedAmount)}, 0)` })
    .from(paymentAllocations)
    .where(
      and(
        eq(paymentAllocations.targetType, 'customer_order'),
        eq(paymentAllocations.targetId, orderId)
      )
    )

  const shouldRefund = order.status === 'pending' && Number(depositPaid) > 0

  // Execute in transaction
  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => client.prepare(sqlStr).run(...(params ?? []))

  let refundPaymentId: string | undefined
  if (shouldRefund) {
    refundPaymentId = crypto.randomUUID()
  }

  try {
    run('BEGIN TRANSACTION')

    // Update order to cancelled
    run(
      'UPDATE customer_orders SET status = ? WHERE id = ?',
      ['cancelled', orderId]
    )

    // Record history entry
    const historyId = crypto.randomUUID()
    run(
      'INSERT INTO customer_order_status_history (id, customer_order_id, status, transitioned_at) VALUES (?, ?, ?, ?)',
      [historyId, orderId, 'cancelled', Date.now()]
    )

    // If refunding: create refund payment + reverse original allocation
    if (shouldRefund && refundPaymentId) {
      const now = Date.now()

      // Create refund payment record
      run(
        'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
        [refundPaymentId, 'cash', Number(depositPaid), now]
      )

      // Reverse the original deposit allocation by setting allocatedAmount to negative
      // This keeps the audit trail intact while effectively cancelling the deposit
      run(
        `UPDATE payment_allocations SET allocated_amount = -${depositPaid} WHERE target_type = 'customer_order' AND target_id = ?`,
        [orderId]
      )
    }

    run('COMMIT')
  } catch (err) {
    try { run('ROLLBACK') } catch {}
    throw err
  }

  // Build result
  const result: CancelOrderResult = { status: 'cancelled' }

  if (refundPaymentId) {
    const [refundPayment] = await db.select().from(payments).where(eq(payments.id, refundPaymentId!))
    result.refundPayment = refundPayment
  }

  return result
}

/**
 * Get status transition history for a customer order (oldest first).
 */
export async function getCustomerOrderHistory(
  orderId: string
): Promise<typeof customerOrderStatusHistory.$inferSelect[]> {
  // Verify order exists
  const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  if (!order) {
    throw new Error(`Customer order not found: ${orderId}`)
  }

  return db.select()
    .from(customerOrderStatusHistory)
    .where(eq(customerOrderStatusHistory.orderId, orderId))
    .orderBy(asc(customerOrderStatusHistory.transitionedAt))
}

// ============================================================================
// Legacy — kept for backward compatibility with existing routes
// ============================================================================

/**
 * Transition a customer order to a new status (legacy — no validation).
 * @deprecated Use transitionCustomerOrder() instead.
 */
export async function updateCustomerOrderStatus(
  orderId: string,
  newStatus: CustomerOrderStatus
): Promise<typeof customerOrders.$inferSelect> {
  return transitionCustomerOrder(orderId, newStatus)
}

