import { Hono } from 'hono'
import {
  createCustomerOrder,
  listCustomerOrders,
  findCustomerOrderById,
  transitionCustomerOrder,
  updateCustomerOrderFields,
  completeCustomerOrder,
  cancelCustomerOrder,
  getCustomerOrderHistory,
  LeasedBicycleDepositError,
  InvalidTransitionError,
  EditabilityError,
  InsufficientPaymentError,
} from '../services/customer-order.service.js'

const ordersRoutes = new Hono()

// ============================================================================
// POST /api/orders — Create a customer order with optional deposit
// ============================================================================

interface ErrorResponse {
  error: string
  code?: string
}

ordersRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result = await createCustomerOrder(rawInput)

    return c.json(
      {
        order: Object.fromEntries(Object.entries(result.order)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item))),
        payment: result.payment ? Object.fromEntries(Object.entries(result.payment)) : undefined,
        allocation: result.allocation ? Object.fromEntries(Object.entries(result.allocation)) : undefined,
      },
      201
    )
  } catch (err) {
    if (err instanceof LeasedBicycleDepositError) {
      return c.json(
        { error: err.message, code: 'LEASED_BICYCLE_DEPOSIT' } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid order input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /api/orders] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /api/orders — List customer orders with optional status filter
// ============================================================================

interface OrdersListResponse {
  orders: Record<string, unknown>[]
  total: number
}

ordersRoutes.get('/', async (c) => {
  const status = c.req.query('status') as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled' | undefined

  const result = await listCustomerOrders(status ? { status } : undefined)

  return c.json({
    orders: result.orders.map(order => Object.fromEntries(Object.entries(order))),
    total: result.total,
  } as OrdersListResponse)
})

// ============================================================================
// GET /api/orders/:id — Get a single order with full details
// ============================================================================

interface OrderDetailResponse {
  order: Record<string, unknown>
  lineItems: Record<string, unknown>[]
  depositPaid: number
}

ordersRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const detail = await findCustomerOrderById(id)
  if (!detail) {
    return c.json({ error: 'Order not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json({
    order: Object.fromEntries(Object.entries(detail.order)),
    lineItems: detail.lineItems.map(item => Object.fromEntries(Object.entries(item))),
    depositPaid: detail.depositPaid,
  } as OrderDetailResponse)
})

// ============================================================================
// PATCH /api/orders/:id/transition — Status transition with validation
// ============================================================================

ordersRoutes.patch('/:id/transition', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const newStatus = body.status as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

  if (!newStatus || !['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'].includes(newStatus)) {
    return c.json(
      { error: 'Invalid status', code: 'VALIDATION_ERROR' } as ErrorResponse,
      400
    )
  }

  try {
    const updated = await transitionCustomerOrder(id, newStatus, {
      expectedDeliveryDate: body.expectedDeliveryDate ?? undefined,
      internalNotes: body.internalNotes !== undefined ? body.internalNotes : undefined,
    })

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof InvalidTransitionError) {
      return c.json(
        { error: err.message, code: 'INVALID_TRANSITION' },
        409
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[PATCH /api/orders/:id/transition] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// PATCH /api/orders/:id — Update editable fields (notes/delivery date)
// ============================================================================

ordersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()

  try {
    const updated = await updateCustomerOrderFields(id, {
      internalNotes: body.internalNotes !== undefined ? body.internalNotes : undefined,
      expectedDeliveryDate: body.expectedDeliveryDate !== undefined ? body.expectedDeliveryDate : undefined,
    })

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof EditabilityError) {
      return c.json(
        { error: err.message, code: 'FIELDS_LOCKED' },
        403
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && err.message.toLowerCase().includes('nothing to update')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' },
        400
      )
    }

    console.error('[PATCH /api/orders/:id] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// POST /api/orders/:id/complete — Collect balance payment → create sale → fulfilled
// ============================================================================

ordersRoutes.post('/:id/complete', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const paymentLines = body.paymentLines as Array<{ method: string; amount: number }>

  if (!Array.isArray(paymentLines) || paymentLines.length === 0) {
    return c.json(
      { error: 'paymentLines is required and must be a non-empty array', code: 'VALIDATION_ERROR' },
      400
    )
  }

  try {
    const result = await completeCustomerOrder(id, paymentLines)

    return c.json({
      order: Object.fromEntries(Object.entries(result.order)),
      sale: Object.fromEntries(Object.entries(result.sale)),
      payments: result.payments.map(p => Object.fromEntries(Object.entries(p))),
      saleLineItems: result.saleLineItems.map(item => Object.fromEntries(Object.entries(item))),
    })
  } catch (err) {
    if (err instanceof InsufficientPaymentError) {
      return c.json(
        { error: err.message, code: 'INSUFFICIENT_PAYMENT', expected: err.expected, provided: err.provided },
        400
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && (err.message.includes('already fulfilled') || err.message.includes('cancelled'))) {
      return c.json(
        { error: err.message, code: 'INVALID_STATE' },
        409
      )
    }

    console.error('[POST /api/orders/:id/complete] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// PATCH /api/orders/:id/cancel — Cancel with refund rules applied
// ============================================================================

ordersRoutes.patch('/:id/cancel', async (c) => {
  const id = c.req.param('id')

  try {
    const result = await cancelCustomerOrder(id)

    return c.json({
      status: result.status,
      refundPayment: result.refundPayment ? Object.fromEntries(Object.entries(result.refundPayment)) : undefined,
    })
  } catch (err) {
    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && (err.message.includes('fulfilled') || err.message.includes('already cancelled'))) {
      return c.json(
        { error: err.message, code: 'INVALID_STATE' },
        409
      )
    }

    console.error('[PATCH /api/orders/:id/cancel] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /api/orders/:id/history — Status transition history (oldest first)
// ============================================================================

ordersRoutes.get('/:id/history', async (c) => {
  const id = c.req.param('id')

  try {
    const history = await getCustomerOrderHistory(id)

    return c.json({
      history: history.map(entry => Object.fromEntries(Object.entries(entry))),
    })
  } catch (err) {
    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[GET /api/orders/:id/history] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// PATCH /api/orders/:id/status — Legacy endpoint (backward compatibility)
// ============================================================================

ordersRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const newStatus = body.status as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

  if (!newStatus || !['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'].includes(newStatus)) {
    return c.json(
      { error: 'Invalid status', code: 'VALIDATION_ERROR' } as ErrorResponse,
      400
    )
  }

  try {
    const updated = await transitionCustomerOrder(id, newStatus)

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof InvalidTransitionError) {
      return c.json(
        { error: err.message, code: 'INVALID_TRANSITION' },
        409
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[PATCH /api/orders/:id/status] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default ordersRoutes

/**
 * Orders feature API client.
 */

import type {
  CustomerOrderDetail,
  CustomerOrderListItem,
  CustomerOrderLineItem,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface OrdersListResponse {
  orders: CustomerOrderListItem[]
  total: number
}

export interface OrderDetailApiResponse {
  order: CustomerOrderDetail
  lineItems: CustomerOrderLineItem[]
  depositPaid: number
}

interface CreateOrderInput {
  customerId: string | null
  lineItems: Array<{
    lineType: 'part' | 'labor' | 'bicycle'
    partId: string | null
    laborServiceId: string | null
    description: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    discountPercent: number | null
    bicycleId: string | null
    bicycleBrand: string | null
    bicycleModel: string | null
    bicycleYear: number | null
    bicycleColor: string | null
    bicycleFrameSize: string | null
  }>
  depositAmount?: number | null
  paymentMethod?: 'cash' | 'card' | 'bank_transfer' | null
  expectedDeliveryDate?: string | null
}

// ---------------------------------------------------------------------------
// API Functions — Order CRUD
// ---------------------------------------------------------------------------

/** Get paginated order list with optional status filter. */
export async function getOrders(statusFilter?: string): Promise<OrdersListResponse> {
  const params = new URLSearchParams()
  if (statusFilter) params.set('status', statusFilter)

  const response = await fetch(`/api/orders?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch orders list')
  }

  return response.json()
}

/** Get a single order by ID with line items and deposit info. */
export async function getOrder(id: string): Promise<OrderDetailApiResponse> {
  const response = await fetch(`/api/orders/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch order')
  }

  return response.json()
}

/** Create a new customer order with optional deposit. */
export async function createOrder(input: CreateOrderInput): Promise<{
  order: CustomerOrderDetail
  lineItems: CustomerOrderLineItem[]
  payment?: Record<string, unknown> | null
  allocation?: Record<string, unknown> | null
}> {
  const response = await fetch('/api/orders', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create order' }))
    throw new Error(error.error || 'Failed to create order')
  }

  return response.json()
}

/** Update the status of a customer order (legacy). */
export async function updateOrderStatus(
  id: string,
  status: 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'
): Promise<CustomerOrderDetail> {
  const response = await fetch(`/api/orders/${id}/status`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update order status' }))
    throw new Error(error.error || 'Failed to update order status')
  }

  const json = await response.json()
  return json.order as CustomerOrderDetail
}

// ---------------------------------------------------------------------------
// API Functions — Lifecycle (new endpoints)
// ---------------------------------------------------------------------------

/** Transition order status with optional fields. */
export async function transitionOrder(
  id: string,
  data: {
    status: 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'
    expectedDeliveryDate?: string | null
    internalNotes?: string | null
  }
): Promise<CustomerOrderDetail> {
  const response = await fetch(`/api/orders/${id}/transition`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to transition order' }))
    throw new Error(error.error || 'Failed to transition order')
  }

  const json = await response.json()
  return json.order as CustomerOrderDetail
}

/** Update editable fields (internalNotes, expectedDeliveryDate). */
export async function updateOrderFields(
  id: string,
  data: { internalNotes?: string | null; expectedDeliveryDate?: string | null }
): Promise<CustomerOrderDetail> {
  const response = await fetch(`/api/orders/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update order fields' }))
    throw new Error(error.error || 'Failed to update order fields')
  }

  const json = await response.json()
  return json.order as CustomerOrderDetail
}

/** Complete order by collecting balance payment. */
export async function completeOrder(
  id: string,
  paymentLines: Array<{ method: 'cash' | 'card' | 'bank_transfer'; amount: number }>
): Promise<{
  order: CustomerOrderDetail
  sale: Record<string, unknown>
  payments: Record<string, unknown>[]
}> {
  const response = await fetch(`/api/orders/${id}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ paymentLines }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to complete order' }))
    throw new Error(error.error || 'Failed to complete order')
  }

  return response.json()
}

/** Cancel order with refund rules applied. */
export async function cancelOrder(id: string): Promise<{
  status: string
  refundPayment?: Record<string, unknown> | null
}> {
  const response = await fetch(`/api/orders/${id}/cancel`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to cancel order' }))
    throw new Error(error.error || 'Failed to cancel order')
  }

  return response.json()
}

/** Get status transition history (oldest first). */
export async function getOrderHistory(id: string): Promise<Array<{
  id: string
  orderId: string
  status: string
  transitionedAt: number
}>> {
  const response = await fetch(`/api/orders/${id}/history`)

  if (!response.ok) {
    throw new Error('Failed to fetch order history')
  }

  const json = await response.json()
  return json.history as Array<{
    id: string
    orderId: string
    status: string
    transitionedAt: number
  }>
}

