/**
 * Order Detail Panel — Shows order header, line items table, deposit info, status transitions,
 * balance collection dialog, cancel confirmation with refund info, and status history timeline.
 */

import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import toast from 'react-hot-toast'
import { ArrowLeft, Package, Wrench, Bike, Clock, CheckCircle2, XCircle, AlertTriangle, CalendarDays, History } from 'lucide-react'
import type { CustomerOrderStatus } from '../types.js'
import { ORDER_STATUS_LABELS, ORDER_STATUS_COLORS, LINE_TYPE_LABELS } from '../types.js'
import {
  getOrder,
  transitionOrder,
  completeOrder,
  cancelOrder,
  getOrderHistory,
  type OrderDetailApiResponse,
} from '../api.js'
import { formatCentsToEuro } from '@/shared/lib/utils'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogHeader, DialogFooter, DialogTitle, DialogDescription } from '@/components/ui/dialog'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface OrderDetailPanelProps {
  orderId: string
}

/** Status transitions allowed from each state */
const STATUS_TRANSITIONS: Record<CustomerOrderStatus, Array<{ to: CustomerOrderStatus; label: string; action?: 'transition' | 'complete' | 'cancel' }>> = {
  pending: [
    { to: 'ordered', label: 'Mark Ordered', action: 'transition' },
    { to: 'cancelled', label: 'Cancel Order', action: 'cancel' },
  ],
  ordered: [
    { to: 'ready', label: 'Mark Ready for Pickup', action: 'transition' },
    { to: 'cancelled', label: 'Cancel Order', action: 'cancel' },
  ],
  ready: [
    { to: 'fulfilled', label: 'Complete & Collect Balance', action: 'complete' },
    { to: 'cancelled', label: 'Cancel Order', action: 'cancel' },
  ],
  fulfilled: [], // terminal state
  cancelled: [], // terminal state
}

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: CustomerOrderStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[status]}`}>
      {ORDER_STATUS_LABELS[status]}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Line Type Icon
// ---------------------------------------------------------------------------

function LineTypeIcon({ lineType }: { lineType: string }) {
  switch (lineType) {
    case 'part': return <Package className="h-4 w-4 text-muted-foreground" />
    case 'labor': return <Wrench className="h-4 w-4 text-muted-foreground" />
    case 'bicycle': return <Bike className="h-4 w-4 text-muted-foreground" />
    default: return null
  }
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

// ---------------------------------------------------------------------------
// Component — Status History Timeline
// ---------------------------------------------------------------------------

interface HistoryEntry {
  id: string
  orderId: string
  status: string
  transitionedAt: number
}

function StatusHistoryTimeline({ history }: { history: HistoryEntry[] }) {
  if (history.length === 0) return null

  return (
    <div className="mt-6">
      <h3 className="text-sm font-medium text-muted-foreground mb-3 flex items-center gap-2">
        <History className="h-4 w-4" /> Status History
      </h3>
      <div className="space-y-0">
        {history.map((entry, index) => (
          <div key={entry.id} className="flex gap-3">
            {/* Timeline line */}
            <div className="flex flex-col items-center">
              <div className={`w-3 h-3 rounded-full border-2 ${index === history.length - 1 ? 'border-primary bg-primary/20' : 'border-muted-foreground/30 bg-background'}`} />
              {index < history.length - 1 && (
                <div className="w-px flex-1 bg-border mt-1" />
              )}
            </div>
            {/* Content */}
            <div className="pb-4">
              <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[entry.status as CustomerOrderStatus] || 'bg-gray-100 text-gray-800'}`}>
                {ORDER_STATUS_LABELS[entry.status as CustomerOrderStatus] ?? entry.status}
              </span>
              <div className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
                <Clock className="h-3 w-3" />
                {new Date(entry.transitionedAt).toLocaleString('en-IE', {
                  year: 'numeric',
                  month: 'short',
                  day: '2-digit',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Balance Payment Dialog
// ---------------------------------------------------------------------------

interface BalancePaymentDialogProps {
  isOpen: boolean
  onClose: () => void
  balanceDue: number
  onConfirm: (paymentLines: Array<{ method: 'cash' | 'card'; amount: number }>) => void
}

function BalancePaymentDialog({ isOpen, onClose, balanceDue, onConfirm }: BalancePaymentDialogProps) {
  const [method, setMethod] = useState<'cash' | 'card'>('cash')
  const [amount, setAmount] = useState(balanceDue)
  const [processing, setProcessing] = useState(false)

  const handleConfirm = async () => {
    if (amount !== balanceDue) {
      toast.error(`Payment must exactly cover balance due: ${formatCentsToEuro(balanceDue)}`)
      return
    }
    setProcessing(true)
    try {
      onConfirm([{ method, amount }])
    } finally {
      setProcessing(false)
    }
  }

  const handleReset = () => {
    setAmount(balanceDue)
    setMethod('cash')
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CheckCircle2 className="h-5 w-5 text-green-600" />
            Collect Balance Payment
          </DialogTitle>
          <DialogDescription>
            Enter payment details to complete this order.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Balance Due */}
          <div className="p-3 bg-muted/50 rounded-md text-sm">
            <span className="text-muted-foreground block text-xs mb-1">Balance Due</span>
            <span className="font-mono text-lg font-semibold">{formatCentsToEuro(balanceDue)}</span>
          </div>

          {/* Payment Method */}
          <div>
            <label className="text-sm font-medium mb-2 block">Payment Method</label>
            <div className="flex gap-2">
              <Button
                variant={method === 'cash' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setMethod('cash')}
              >
                Cash
              </Button>
              <Button
                variant={method === 'card' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setMethod('card')}
              >
                Card
              </Button>
            </div>
          </div>

          {/* Amount */}
          <div>
            <label className="text-sm font-medium mb-2 block">Amount (€)</label>
            <input
              type="number"
              step="0.01"
              min="0"
              value={amount / 100 || ''}
              onChange={(e) => setAmount(Math.round(parseFloat(e.target.value || '0') * 100))}
              className="w-full px-3 py-2 border rounded-md text-sm font-mono focus:outline-none focus:ring-2 focus:ring-primary"
            />
          </div>

          {/* Validation */}
          {amount !== balanceDue && (
            <div className="flex items-center gap-2 text-xs text-red-600">
              <AlertTriangle className="h-4 w-4" />
              Amount must exactly match balance due ({formatCentsToEuro(balanceDue)})
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" size="sm" onClick={onClose}>
            Cancel
          </Button>
          <Button size="sm" onClick={handleReset} variant="secondary">
            Reset
          </Button>
          <Button
            size="sm"
            onClick={handleConfirm}
            disabled={processing || amount !== balanceDue}
          >
            {processing ? 'Processing…' : 'Collect Payment'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ---------------------------------------------------------------------------
// Component — Cancel Confirmation Dialog
// ---------------------------------------------------------------------------

interface CancelConfirmDialogProps {
  isOpen: boolean
  onClose: () => void
  currentStatus: CustomerOrderStatus
  depositPaid: number
  onConfirm: () => void
}

function CancelConfirmDialog({ isOpen, onClose, currentStatus, depositPaid, onConfirm }: CancelConfirmDialogProps) {
  const [processing, setProcessing] = useState(false)

  const isRefundable = currentStatus === 'pending' && depositPaid > 0

  const handleConfirm = async () => {
    setProcessing(true)
    try {
      await onConfirm()
    } finally {
      setProcessing(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-red-600">
            <XCircle className="h-5 w-5" />
            Cancel Order
          </DialogTitle>
          <DialogDescription>
            Are you sure you want to cancel this order? This action cannot be undone.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Refund Info */}
          {isRefundable ? (
            <div className="p-3 bg-green-50 border border-green-200 rounded-md text-sm dark:bg-green-900/20 dark:border-green-800">
              <div className="flex items-center gap-2 mb-1">
                <CheckCircle2 className="h-4 w-4 text-green-600" />
                <span className="font-medium text-green-700 dark:text-green-400">Deposit Refundable</span>
              </div>
              <p className="text-muted-foreground">
                Since the order is still pending, your deposit of{' '}
                <strong>{formatCentsToEuro(depositPaid)}</strong> will be refunded.
              </p>
            </div>
          ) : (
            <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-md text-sm dark:bg-yellow-900/20 dark:border-yellow-800">
              <div className="flex items-center gap-2 mb-1">
                <AlertTriangle className="h-4 w-4 text-yellow-600" />
                <span className="font-medium text-yellow-700 dark:text-yellow-400">Deposit Non-Refundable</span>
              </div>
              {depositPaid > 0 ? (
                <p className="text-muted-foreground">
                  The deposit of <strong>{formatCentsToEuro(depositPaid)}</strong> is non-refundable at this stage.
                  No automatic financial adjustment will be made — handle externally if needed.
                </p>
              ) : (
                <p className="text-muted-foreground">
                  No deposit was collected for this order.
                </p>
              )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" size="sm" onClick={onClose}>
            Keep Order
          </Button>
          <Button
            variant="destructive"
            size="sm"
            onClick={handleConfirm}
            disabled={processing}
          >
            {processing ? 'Cancelling…' : 'Cancel Order'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ---------------------------------------------------------------------------
// Component — Mark Ordered Dialog (with delivery date picker)
// ---------------------------------------------------------------------------

interface MarkOrderedDialogProps {
  isOpen: boolean
  onClose: () => void
  onConfirm: (data: { expectedDeliveryDate?: string | null; internalNotes?: string | null }) => void
}

function MarkOrderedDialog({ isOpen, onClose, onConfirm }: MarkOrderedDialogProps) {
  const [deliveryDate, setDeliveryDate] = useState('')
  const [notes, setNotes] = useState('')
  const [processing, setProcessing] = useState(false)

  const handleConfirm = async () => {
    setProcessing(true)
    try {
      onConfirm({
        expectedDeliveryDate: deliveryDate || null,
        internalNotes: notes || null,
      })
    } finally {
      setProcessing(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CalendarDays className="h-5 w-5 text-blue-600" />
            Mark Order as Ordered
          </DialogTitle>
          <DialogDescription>
            Set the expected delivery date and any internal notes.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Delivery Date */}
          <div>
            <label className="text-sm font-medium mb-2 block flex items-center gap-1">
              <CalendarDays className="h-4 w-4" /> Expected Delivery Date
            </label>
            <input
              type="date"
              value={deliveryDate}
              onChange={(e) => setDeliveryDate(e.target.value)}
              className="w-full px-3 py-2 border rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-primary"
            />
          </div>

          {/* Internal Notes */}
          <div>
            <label className="text-sm font-medium mb-2 block">Internal Notes</label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={3}
              maxLength={2000}
              placeholder="Optional notes for internal use…"
              className="w-full px-3 py-2 border rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-primary resize-y"
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" size="sm" onClick={onClose}>
            Cancel
          </Button>
          <Button
            size="sm"
            onClick={handleConfirm}
            disabled={processing}
          >
            {processing ? 'Processing…' : 'Mark Ordered'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ---------------------------------------------------------------------------
// Component — Order Detail Panel (Main)
// ---------------------------------------------------------------------------

export function OrderDetailPanel({ orderId }: OrderDetailPanelProps) {
  const navigate = useNavigate()
  const [detail, setDetail] = useState<OrderDetailApiResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [transitioning, setTransitioning] = useState(false)

  // Dialog states
  const [showBalanceDialog, setShowBalanceDialog] = useState(false)
  const [showCancelDialog, setShowCancelDialog] = useState(false)
  const [showMarkOrderedDialog, setShowMarkOrderedDialog] = useState(false)

  // History state
  const [history, setHistory] = useState<HistoryEntry[]>([])

  // Fetch order detail + history
  const fetchOrder = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [orderData, historyData] = await Promise.all([
        getOrder(orderId),
        getOrderHistory(orderId).catch(() => [] as HistoryEntry[]),
      ])
      setDetail(orderData)
      setHistory(historyData)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load order')
    } finally {
      setLoading(false)
    }
  }, [orderId])

  useEffect(() => {
    fetchOrder()
  }, [fetchOrder])

  // Handle status transition
  const handleTransition = async (newStatus: CustomerOrderStatus, options?: { expectedDeliveryDate?: string | null; internalNotes?: string | null }) => {
    setTransitioning(true)
    try {
      await transitionOrder(orderId, { status: newStatus, ...options })
      toast.success(`Order marked as ${ORDER_STATUS_LABELS[newStatus].toLowerCase()}`)
      await fetchOrder()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update status')
    } finally {
      setTransitioning(false)
    }
  }

  // Handle complete order with balance collection
  const handleComplete = async (paymentLines: Array<{ method: 'cash' | 'card'; amount: number }>) => {
    setTransitioning(true)
    try {
      await completeOrder(orderId, paymentLines as Array<{ method: 'cash' | 'card' | 'bank_transfer'; amount: number }>)
      toast.success('Balance collected — order fulfilled!')
      setShowBalanceDialog(false)
      await fetchOrder()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to complete order')
    } finally {
      setTransitioning(false)
    }
  }

  // Handle cancel order
  const handleCancel = async () => {
    setTransitioning(true)
    try {
      await cancelOrder(orderId)
      toast.success('Order cancelled')
      setShowCancelDialog(false)
      await fetchOrder()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to cancel order')
    } finally {
      setTransitioning(false)
    }
  }

  // Handle transition button click
  const handleActionClick = async (transition: { to: CustomerOrderStatus; action?: string }) => {
    if (transition.action === 'cancel') {
      setShowCancelDialog(true)
    } else if (transition.action === 'complete') {
      setShowBalanceDialog(true)
    } else if (transition.to === 'ordered') {
      // Open dialog to set delivery date
      setShowMarkOrderedDialog(true)
    } else {
      // Simple transition
      await handleTransition(transition.to)
    }
  }

  // Back to list
  const handleBack = () => navigate('/orders')

  if (loading) {
    return (
      <div className="flex flex-col h-full">
        <CardHeader className="pb-2 px-6 pt-4">
          <CardTitle className="text-xl">Loading order…</CardTitle>
        </CardHeader>
      </div>
    )
  }

  if (error || !detail) {
    return (
      <div className="flex flex-col h-full">
        <CardHeader className="pb-2 px-6 pt-4">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="sm" onClick={handleBack}>
              <ArrowLeft className="h-4 w-4 mr-1" /> Back
            </Button>
          </div>
        </CardHeader>
        <CardContent className="px-6 pb-6">
          <div className="p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error || 'Order not found'}
          </div>
        </CardContent>
      </div>
    )
  }

  const { order, lineItems, depositPaid } = detail
  const availableTransitions = STATUS_TRANSITIONS[order.status] ?? []
  const balanceDue = Math.max(0, order.totalPriceNet - depositPaid)

  // Compute totals from line items
  const totalNet = lineItems.reduce((sum, item) => sum + item.lineTotalNet, 0)
  const totalVat = lineItems.reduce((sum, item) => sum + item.lineTotalVat, 0)
  const totalGross = lineItems.reduce((sum, item) => sum + item.lineTotalGross, 0)

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="sm" onClick={handleBack}>
              <ArrowLeft className="h-4 w-4 mr-1" /> Back
            </Button>
            <CardTitle className="text-xl">{order.orderNumber}</CardTitle>
            <StatusBadge status={order.status} />
          </div>

          {/* Status transition buttons */}
          {availableTransitions.length > 0 && (
            <div className="flex gap-2">
              {availableTransitions.map((transition) => {
                const isCancel = transition.action === 'cancel'
                const isComplete = transition.action === 'complete'
                return (
                  <Button
                    key={transition.to}
                    variant={isCancel ? 'outline' : isComplete ? 'default' : 'secondary'}
                    size="sm"
                    onClick={() => handleActionClick(transition)}
                    disabled={transitioning}
                    className={isCancel ? 'text-red-600 hover:text-red-700 border-red-200' : ''}
                  >
                    {transition.label}
                  </Button>
                )
              })}
            </div>
          )}
        </div>
      </CardHeader>

      {/* Content */}
      <CardContent className="px-6 pb-6 flex-1 overflow-auto space-y-6">
        {/* Order Info Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
          <div>
            <span className="text-muted-foreground block text-xs">Customer</span>
            <span className="font-medium">{order.customerId ? `ID: ${order.customerId.slice(0, 8)}…` : 'Unknown'}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Created</span>
            <span>{formatDate(order.createdAt)}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Expected Delivery</span>
            <span>{formatDate(order.expectedDeliveryDate)}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Deposit Paid</span>
            <span className="font-mono">{formatCentsToEuro(depositPaid)}</span>
          </div>
        </div>

        {/* Balance Due Summary */}
        {depositPaid > 0 && order.status !== 'fulfilled' && order.status !== 'cancelled' && (
          <div className="p-4 bg-accent rounded-md text-sm">
            <h3 className="font-medium mb-2">Payment Summary</h3>
            <div className="grid grid-cols-3 gap-4">
              <div>
                <span className="text-muted-foreground block text-xs">Total (net)</span>
                <span className="font-mono">{formatCentsToEuro(totalNet)}</span>
              </div>
              <div>
                <span className="text-muted-foreground block text-xs">Deposit Paid</span>
                <span className="font-mono text-green-600 dark:text-green-400">{formatCentsToEuro(depositPaid)}</span>
              </div>
              <div>
                <span className="text-muted-foreground block text-xs">Balance Due</span>
                <span className="font-mono font-semibold">{formatCentsToEuro(balanceDue)}</span>
              </div>
            </div>
          </div>
        )}

        {/* Internal Notes */}
        {order.internalNotes && (
          <div className="p-3 bg-muted/50 rounded-md text-sm">
            <span className="text-muted-foreground block text-xs mb-1">Internal Notes</span>
            <span>{order.internalNotes}</span>
          </div>
        )}

        {/* Line Items Table */}
        <div>
          <h3 className="text-sm font-medium text-muted-foreground mb-2">Line Items ({lineItems.length})</h3>
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50 border-b">
                  <th className="text-left px-4 py-2 font-medium text-muted-foreground w-16">Type</th>
                  <th className="text-left px-4 py-2 font-medium text-muted-foreground">Description</th>
                  <th className="text-center px-4 py-2 font-medium text-muted-foreground w-16">Qty</th>
                  <th className="text-right px-4 py-2 font-medium text-muted-foreground w-28">Unit Price</th>
                  <th className="text-right px-4 py-2 font-medium text-muted-foreground w-28">Total (net)</th>
                </tr>
              </thead>
              <tbody>
                {lineItems.map((item) => (
                  <tr key={item.id} className="border-b last:border-b-0 hover:bg-muted/30 transition-colors">
                    <td className="px-4 py-2">
                      <div className="flex items-center gap-1.5">
                        <LineTypeIcon lineType={item.lineType} />
                        <span className="text-xs text-muted-foreground">{LINE_TYPE_LABELS[item.lineType as keyof typeof LINE_TYPE_LABELS] ?? item.lineType}</span>
                      </div>
                    </td>
                    <td className="px-4 py-2">{item.description}</td>
                    <td className="px-4 py-2 text-center tabular-nums">{item.quantity}</td>
                    <td className="px-4 py-2 text-right font-mono tabular-nums">{formatCentsToEuro(item.unitPriceNet)}</td>
                    <td className="px-4 py-2 text-right font-mono tabular-nums">{formatCentsToEuro(item.lineTotalNet)}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="bg-muted/30">
                  <td colSpan={4} className="px-4 py-2 text-right font-medium">Totals:</td>
                  <td className="px-4 py-2 text-right font-mono tabular-nums">
                    <div className="text-xs space-y-0.5">
                      <div className="flex justify-between gap-8">
                        <span className="text-muted-foreground">Net:</span>
                        <span>{formatCentsToEuro(totalNet)}</span>
                      </div>
                      <div className="flex justify-between gap-8 text-xs text-muted-foreground">
                        <span>VAT:</span>
                        <span>{formatCentsToEuro(totalVat)}</span>
                      </div>
                      <div className="flex justify-between gap-8 font-medium border-t pt-1 mt-1">
                        <span>Gross:</span>
                        <span>{formatCentsToEuro(totalGross)}</span>
                      </div>
                    </div>
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        {/* Status History Timeline */}
        <StatusHistoryTimeline history={history} />
      </CardContent>

      {/* Dialogs */}
      {order.status !== 'fulfilled' && order.status !== 'cancelled' && (
        <>
          <BalancePaymentDialog
            isOpen={showBalanceDialog}
            onClose={() => setShowBalanceDialog(false)}
            balanceDue={balanceDue}
            onConfirm={handleComplete}
          />

          <CancelConfirmDialog
            isOpen={showCancelDialog}
            onClose={() => setShowCancelDialog(false)}
            currentStatus={order.status}
            depositPaid={depositPaid}
            onConfirm={handleCancel}
          />

          {availableTransitions.some(t => t.to === 'ordered') && (
            <MarkOrderedDialog
              isOpen={showMarkOrderedDialog}
              onClose={() => setShowMarkOrderedDialog(false)}
              onConfirm={(data) => handleTransition('ordered', data)}
            />
          )}
        </>
      )}
    </div>
  )
}

