/**
 * OrderDetailPanel — Component tests.
 *
 * Verifies:
 * - Renders order number, status badge, customer info
 * - Shows line items table with correct totals
 * - Displays deposit summary when depositPaid > 0
 * - Status transition buttons appear based on current status
 * - Back button navigates to orders list
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter, Routes, Route } from 'react-router-dom'
import type { OrderDetailApiResponse } from '../../api.js'
import * as apiModule from '../../api.js'

// ---------------------------------------------------------------------------
// Mocks — hoisted before module imports
// ---------------------------------------------------------------------------

vi.mock('@/shared/lib/utils.js', () => ({
  cn: (...inputs: string[]) => inputs.filter(Boolean).join(' '),
  formatCentsToEuro: (cents: number) => `€${(cents / 100).toFixed(2)}`,
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createOrderDetail(overrides?: Partial<OrderDetailApiResponse>): OrderDetailApiResponse {
  return {
    order: {
      id: 'order-001',
      orderNumber: 'CO-0001',
      customerId: 'cust-abc-123',
      status: 'pending',
      totalPriceNet: 7000,
      expectedDeliveryDate: null,
      internalNotes: null,
      createdAt: 1706832000000, // Feb 2, 2024
    },
    lineItems: [
      {
        id: 'li-001',
        orderId: 'order-001',
        lineType: 'part',
        partId: 'p1',
        laborServiceId: null,
        description: 'Bearing 6205',
        quantity: 2,
        unitPriceNet: 1000,
        vatRateId: 'vat-standard',
        discountPercent: null,
        lineTotalNet: 2000,
        lineTotalVat: 420,
        lineTotalGross: 2420,
        bicycleId: null,
        bicycleBrand: null,
        bicycleModel: null,
        bicycleYear: null,
        bicycleColor: null,
        bicycleFrameSize: null,
      },
      {
        id: 'li-002',
        orderId: 'order-001',
        lineType: 'labor',
        partId: null,
        laborServiceId: 'ls-1',
        description: 'Installation',
        quantity: 1,
        unitPriceNet: 5000,
        vatRateId: 'vat-standard',
        discountPercent: null,
        lineTotalNet: 5000,
        lineTotalVat: 1050,
        lineTotalGross: 6050,
        bicycleId: null,
        bicycleBrand: null,
        bicycleModel: null,
        bicycleYear: null,
        bicycleColor: null,
        bicycleFrameSize: null,
      },
    ],
    depositPaid: 0,
    ...overrides,
  }
}

// Dynamic import to get the mocked module after mocks are set up
let OrderDetailPanel: typeof import('../OrderDetailPanel.js').OrderDetailPanel

beforeEach(async () => {
  vi.clearAllMocks()
  const mod = await import('../OrderDetailPanel.js')
  OrderDetailPanel = mod.OrderDetailPanel
})

function renderPanel(orderId = 'order-001') {
  return render(
    <MemoryRouter initialEntries={['/orders/order-001']}>
      <Routes>
        <Route path="/orders/:id" element={<OrderDetailPanel orderId={orderId} />} />
        <Route path="/orders" element={<div data-testid="orders-list">Orders List</div>} />
      </Routes>
    </MemoryRouter>
  )
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('OrderDetailPanel', () => {
  it('renders order number and status badge', async () => {
    const detail = createOrderDetail()
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('CO-0001')).toBeInTheDocument()
    })

    expect(screen.getByText('Pending')).toBeInTheDocument()
  })

  it('renders line items table with descriptions and quantities', async () => {
    const detail = createOrderDetail()
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Bearing 6205')).toBeInTheDocument()
      expect(screen.getByText('Installation')).toBeInTheDocument()
    })
  })

  it('displays deposit summary when depositPaid > 0', async () => {
    const detail = createOrderDetail({
      depositPaid: 1500,
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Deposit Summary')).toBeInTheDocument()
    })
  })

  it('does not display deposit summary when depositPaid is 0', async () => {
    const detail = createOrderDetail({
      depositPaid: 0,
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.queryByText('Deposit Summary')).not.toBeInTheDocument()
    })
  })

  it('shows status transition buttons for pending orders', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, status: 'pending' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Mark Ordered')).toBeInTheDocument()
      expect(screen.getByText('Cancel Order')).toBeInTheDocument()
    })
  })

  it('shows no transition buttons for fulfilled orders', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, status: 'fulfilled' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.queryByText('Mark Ordered')).not.toBeInTheDocument()
      expect(screen.queryByText('Cancel Order')).not.toBeInTheDocument()
    })
  })

  it('shows no transition buttons for cancelled orders', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, status: 'cancelled' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.queryByText('Mark Ordered')).not.toBeInTheDocument()
      expect(screen.queryByText('Cancel Order')).not.toBeInTheDocument()
    })
  })

  it('displays error when order fetch fails', async () => {
    vi.spyOn(apiModule, 'getOrder').mockRejectedValueOnce(new Error('Failed to load order'))

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText(/Failed to load order/i)).toBeInTheDocument()
    })
  })

  it('displays internal notes when present', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, internalNotes: 'Customer requested express delivery' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Internal Notes')).toBeInTheDocument()
      expect(screen.getByText('Customer requested express delivery')).toBeInTheDocument()
    })
  })
})

